window.harnessChunks["rows-008df588e250d195.js"]=["<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-09-17T03:12:19+03:00\"><th scope=\"row\"><a href=\"https://github.com/proliferate-ai/proliferate\" target=\"_blank\" rel=\"noopener\">Proliferate</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-16\">2026-09-16</time></td><td class=\"review-ref\"><a href=\"https://github.com/proliferate-ai/proliferate/tree/74e1178cf3ecfbfc3ffeb8321f82c4a9bfce620f\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 74e1178cf3ecfbfc3ffeb8321f82c4a9bfce620f\">74e1178 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: standard product sessions run native coding-agent harnesses that autonomously inspect, edit and execute work inside bounded task workspaces; child sessions can independently complete delegated scoped work and return results.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: first-party isolation, parent→child messaging and exact completion wakeups are conflict avoidance/delegation mechanisms. The pinned implementation does not provide an agent-owned mutual-adjustment loop that observes and dampens interference or oscillation among peer S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: the product control plane provisions workspaces, sessions and workflows, while a parent may supervise its own delegated children, but no distinct autonomous actor is given current-whole authority to regulate shared resources, commitments or priorities across the operational system. Scheduling/provisioning alone is not Beer S3.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: the first-party review runtime establishes an independent audit path. Review-only agents inspect trusted plan/code targets, are prohibited from modifying them, submit structured pass/critique results, and return findings to the parent session. The runtime can automatically iterate parent revision → trusted recapture → fresh review round until pass or a configured round limit. This is a ready, agent-enacted complementary audit/feedback loop rather than a developer-supplied verifier primitive.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: recurring/event-driven workflows react to configured events and can run tasks such as triage or dependency updates, but the pinned distribution does not establish a persistent agent-owned external/prospective intelligence function that models environmental change and feeds adaptation into present control.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: harness choice, workflow definitions, reviewer configuration, permissions and review policy remain product/operator configuration. No first-party agent holds final authority over organizational identity, purpose or constitutional policy.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/ff74c380425fb7c8a9cee512289cdb428d74dbb1/assessments/proliferate.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit ff74c380425fb7c8a9cee512289cdb428d74dbb1\">ff74c38 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-09-24T22:25:19+00:00\"><th scope=\"row\"><a href=\"https://github.com/Growth-Circle/cadis\" target=\"_blank\" rel=\"noopener\">C.A.D.I.S.</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-25\">2026-09-25</time></td><td class=\"review-ref\"><a href=\"https://github.com/Growth-Circle/cadis/tree/52c55854b1abbcda82839b7a934cbdb16a69b635\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 52c55854b1abbcda82839b7a934cbdb16a69b635\">52c5585 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: execute user objectives through a model-driven tool/action loop that receives environment/tool observations and chooses subsequent operational action until completion. - Disturbance / variety regulated: request ambiguity, workspace/file/git/shell state, tool results, provider responses, failed actions and intermediate evidence that changes the next useful operational step. - Decisive decision or feedback right: choose which available tool/action to invoke, its arguments, whether further action is needed and the final operational response within configured safety/step bounds. - Decision owner: the model-driven CADIS agent running through the daemon&#39;s first-party generation/tool loop. - Supporting / enforcement mechanisms: provider adapters, parsetoolcalldirectives, native tool registry, workspace grants, policy engine, approvals, session/step limits, persistence and daemon event streaming. - Closure path: request enters cadisd → routed agent/model generates a tool directive or response → daemon executes the selected tool under policy/workspace controls → tool results are placed into a follow-up prompt → model chooses the next action or completes → result returns to the caller/environment. - Boundary reachability: ordinary message.send through the shipped daemon executes this first-party loop; no downstream organizational actor must be supplied to obtain model/action/feedback closure. - Why this is / is not agent-owned: policy, grants and bounds can reject or constrain choices, but they do not predetermine the substantive tool/action sequence. Removing the model actor removes the ordinary operational decision path. - Evidence: crates/cadis-daemon/src/main.rs; crates/cadis-core/src/lib.rs; README.md. - Basis: explicit + structural - Confidence: high - Caveats: direct client commands and deterministic policy/approval branches also exist. A is based on the standard model-owned tool/action path, not on every request transition being autonomous.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: attenuate interference among distinct concurrently active CADIS operational agents/workers by isolating project mutations and bounding shared worker concurrency. - Disturbance / variety regulated: parallel coding units can corrupt or overwrite the same working tree, while unbounded fan-out can consume shared daemon capacity and delay peer work. - Decisive decision or feedback right: choose/revise the cross-S1 isolation and shared-concurrency regime that determines where a coding worker may mutate files and whether another worker may begin now or must wait. - Decision owner: no autonomous first-party S2 actor owns that regime. The standard daemon supplies the function-specific worktree/queue relation and deterministically enforces parent/configured limits, leaving revision of the regime outside autonomous S2 ownership. - Supporting / enforcement mechanisms: per-worker worktree intent and metadata, Git worktree creation, workspace/grant checks, worktree-local worker command cwd, maxconcurrentworkers, global running-worker count, queued worker state and slot-release/start logic. - Closure path: multiple S1 tasks enter parallel worker execution → daemon allocates project work into separate owned worktrees and counts current running workers → excess workers remain Queued and isolated workers operate on separate branches/paths → freed slots start waiting workers and their subsequent execution proceeds under the isolated context. - Boundary reachability: worktree-backed worker operation and global worker admission are shipped daemon/core paths at the pinned revision; callers do not need to implement their own isolation or worker queue. - Why this is / is not agent-owned: the disturbance and attenuation relation are first-party and specific to cross-unit interference, but isolation/admission outcomes are mechanically derived from configured policy rather than selected by an autonomous coordinating model. This supports C, not A. - Evidence: crates/cadis-core/src/lib.rs; docs/10RISKREGISTER.md; README.md. - Basis: explicit + structural - Confidence: high - Caveats: generic @agent routing and child-agent spawning are not credited as S2 by themselves. Positive credit rests on the documented parallel-edit/resource disturbances and the first-party isolation/backpressure relation. - Distinct S1 units: two or more separately routed/spawned model-driven agents/agent sessions executing operational tasks inside the same cadisd, including coding tasks represented by daemon-managed worker records. - Inter-S1 disturbance: simultaneous project mutations can conflict on the same repository state, and concurrent worker fan-out can exceed shared worker execution capacity even when each task is locally valid. - Attenuating coordination relation: CADIS assigns project workers separate Git worktrees and applies a daemon-wide maximum number of running workers, holding excess work in Queued state. - Feedback into subsequent S1 behaviour: the owned worktree becomes the worker&#39;s execution context/cwd for validation and artifacts, while queued workers do not begin until a shared slot is released; both relations change where or when each S1&#39;s next operation occurs. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the credited mechanisms are explicitly aimed at cross-agent file-conflict and aggregate fan-out disturbances, not merely at transporting messages, naming specialists or ordering a task graph.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A(P) - Function: maintain a current organization-wide view of agent commitments and use it to allocate/change present operational work, with an additional legitimate parent/operator intervention mode. - Disturbance / variety regulated: duplicated or poorly allocated agent work, changing agent/session status, current task commitments, runaway/unwanted current activity and aggregate worker pressure can make the daemon&#39;s present operation incoherent or exceed current capacity. - Decisive decision or feedback right: autonomous mode — decide from current all-agent state whether to create a new child agent and assign it a task; parent mode — inspect the current roster and terminate an agent or cancel a session, removing associated current commitments/workers from later operation. - Decision owner: autonomous mode — the main CADIS model actor receiving first-party current runtime state; parent mode — the legitimate self-hosting operator using shipped CLI/HUD/protocol controls. - Supporting / enforcement mechanisms: orchestratorawarenesscontext(), agent/session registries and sorted snapshots, recent-session task/step summaries, bounded model-driven [SPAWN] parsing, spawn limits, global worker scheduler, agent.list, agent.kill, session.cancel, persistence and cancellation propagation. - Closure path: current agent roster/session state is assembled → injected into the main agent&#39;s prompt → main model selects a new child role/task when current organization needs it → runtime creates the child and task-bearing session → subsequent organization state includes the changed commitment. In parent mode, roster inspection → kill/cancel request → agent/session and non-terminal associated worker cancellation → subsequent live operation reflects the intervention. - Boundary reachability: whole-agent awareness and model-driven child spawning are standard first-party runtime paths; parent list/kill/cancel operations are stable shipped protocol/CLI/HUD surfaces. - Why this is / is not agent-owned: the main actor receives whole-organization current state rather than only one delegated task and autonomously changes current commitments. Deterministic spawn/worker limits constrain that authority but do not choose the child task. The parent path is separately owned by the operator, producing the (P) modifier. - Evidence: crates/cadis-core/src/lib.rs; docs/29PROTOCOLFREEZE.md; crates/cadis-cli/src/main.rs. - Basis: explicit + structural - Confidence: medium-high - Caveats: ordinary delegation is not credited as S3 by itself. The positive autonomous mapping depends specifically on the main agent&#39;s injected whole-roster/recent-session state plus its live model-owned commitment-creation path. Worker concurrency limits are supporting current-control enforcement, not the reason for A. - Whole-system current view: orchestratorawarenesscontext() enumerates the current agent roster with status, specialist and latest task and also includes recent agent sessions with state and step/budget progress; this generated state is injected into the main orchestrator prompt. - Current-control decision scope: autonomous creation/allocation of new child-agent commitments in response to current organization state, plus parent termination/cancellation of existing live commitments; daemon worker admission additionally constrains concurrent execution.\">A(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material first-party complementary audit path is established for the declared CADIS operating boundary at the pinned revision. - Disturbance / variety regulated: not established. - Decisive decision or feedback right: not established. - Decision owner: none established. - Supporting / enforcement mechanisms: optional reviewer/tester specialist roles, worker validation commands/test-report artifacts, patch-apply preflight, policy checks, approvals, logs and lifecycle events. - Closure path: not established as S3. These paths validate ordinary outputs or expose ordinary evidence but do not establish a materially independent complementary challenge of an S1/S3 operational claim with a required corrective return. - Why this is / is not agent-owned: a role named Reviewer can be spawned/routed, but it uses the common agent contract and is not packaged as a mandatory complementary audit owner with distinct evidence access/authority. Deterministic validation/preflight is routine production QA/integrity control. - Evidence: docs/standards/10AGENTSTANDARD.md; crates/cadis-core/src/lib.rs; docs/29PROTOCOLFREEZE.md. - Basis: explicit + structural absence - Confidence: medium-high - Caveats: a downstream organization can deliberately instantiate a reviewer with different workspace/test access. That would be a separate system-in-focus and does not upgrade the standard CADIS distribution here.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material first-party outside-and-then adaptation loop is established for the declared CADIS operating boundary at the pinned revision. - Disturbance / variety regulated: not established as prospective adaptation. - Decisive decision or feedback right: not established. - Decision owner: none established. - Supporting / enforcement mechanisms: persistent memory records/capsules, workspace/project facts, correction/procedure memory kinds, provider/model selection, specialist personas, configuration reload and project/workspace state. - Closure path: no first-party operating path was found that distinguishes an external/future capability issue, generates an adaptation option, selects it and returns a changed capability or S3 regime into subsequent operation. - Why this is / is not agent-owned: cadis-memory can store candidate records, explicitly promote/reject them and inject already-confirmed capsules, but cadis-core only consumes confirmed memory. The standard runtime does not wire autonomous evidence-to-adaptation proposal/selection/promotion closure. - Evidence: crates/cadis-memory/src/lib.rs; crates/cadis-core/src/lib.rs. - Basis: explicit + structural absence -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no material first-party identity/ultimate-policy authority loop is established for the declared CADIS operating boundary at the pinned revision. - Disturbance / variety regulated: not established at identity/ultimate-policy level. - Decisive decision or feedback right: no legitimate first-party ultimate authority is wired to adjudicate or amend the organization&#39;s governing identity/policy when such an issue arises. - Decision owner: none established. - Supporting / enforcement mechanisms: hardcoded/default CADIS identity prompt, specialist persona fields and agent.specialist.set, central policy engine, workspace grants, risk classes, approval state and ordinary model/provider configuration. - Closure path: no identity/ultimate-policy issue → legitimate authority → adjudication/amendment → subsequent-operation-under-new-policy chain is established. - Why this is / is not agent-owned: the named CADIS persona and parent-editable specialist persona configure operating roles; policy/approval components enforce already-selected constraints. Neither surface establishes ultimate-policy ownership merely because it changes prompts or blocks risky actions. - Evidence: crates/cadis-core/src/lib.rs; docs/29PROTOCOLFREEZE.md; crates/cadis-policy/src/lib.rs. - Basis: explicit + structural absence - Confidence: high - Caveats: agent.specialist.set and parent configuration can materially change behavior, but task/role/persona configuration is not automatically the organization&#39;s identity/ultimate-policy function.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/76cc1d6c195ab75cb4dea51f540dd3d685cf4700/assessments/cadis.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 76cc1d6c195ab75cb4dea51f540dd3d685cf4700\">76cc1d6 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-09-18T21:27:31+03:00\"><th scope=\"row\"><a href=\"https://github.com/ZJU-REAL/ClawGUI\" target=\"_blank\" rel=\"noopener\">ClawGUI</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-18\">2026-09-18</time></td><td class=\"review-ref\"><a href=\"https://github.com/ZJU-REAL/ClawGUI/tree/d990d3e3f2390ced708771d9681d3c4f9a6cbef5\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision d990d3e3f2390ced708771d9681d3c4f9a6cbef5\">d990d3e &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A. - Function: execute user-requested GUI/device outcomes through autonomous perception, planning/tool orchestration and screen actions. - Disturbance / variety regulated: changing UI state, device/application differences, task instructions, failed actions and environmental interruptions. - Decisive decision or feedback right: model-driven agent actors choose operational plans/actions and adapt to observed device state. - Decision owner: autonomous brain/GUI-agent actor in the first-party deployment path. - Supporting / enforcement mechanisms: device adapters, sessions, memory, chat surfaces and skill retrieval/injection. - Closure path: actions change device state, subsequent screen observations return to the agent and drive later actions until completion/failure. - Basis /\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: —. - The two-agent brain/phone architecture separates responsibilities and tool execution, but the pinned evidence does not establish a concrete inter-S1 interference/conflict/oscillation plus a mutual-adjustment loop that attenuates it. Orchestration/delegation alone is not S2. -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: —. - The brain orchestrates a task and the runtime manages sessions/device execution, but no distinct first-party actor is evidenced with current whole-organization visibility plus discretionary authority over shared resources, priorities or commitments across multiple operational S1s. -\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A. - Claim being audited: whether the operating PhoneAgent actually achieved the user&#39;s GUI task and, when not, where observable execution first departed from success. - Ordinary reporting path: executor rollout/actions and its normal task outcome. - Complementary access path: an explicitly independent verifier receives only sealed external evidence — screenshots, action log, accessibility/DOM data, final state and optional prior assertions — and never sees the executor&#39;s reasoning, plans or skill package. - Independence boundary: the verifier is instructed to judge only observable evidence and cannot modify the executor&#39;s playbook itself. - Decisive judgment / owner: the verifier model independently determines task success, failure type/step, root cause and behavioral corrections. - Supporting mechanisms: strict JSON schema, evidence packaging and restricted skill-file tools. - Closure path: failed verification feeds a separate skillrevise step that is required to change the skill package; when a revision is produced, PhoneAgent immediately retries using the changed capability. - Why this is S3: the path provides materially different access to operational reality, an independent judgment boundary and explicit corrective return rather than routine executor self-checking. - Basis /\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: —. - The evolve loop changes future procedural capability, but its trigger and evidence are failures from the system&#39;s own current GUI-task execution. It does not establish an external-and-prospective model of changing users, threats, tools or future conditions that develops adaptation options in a two-way S3/S4 conversation. - Self-improvement alone is therefore not promoted to S4. -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: —. - User requests, model/configuration choices, skill modes and restricted edit surfaces constrain operation, but no runtime identity/ultimate-policy authority loop is evidenced at this recursion. -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/4155c4340e1b7a5ca09b5decae990b0a6948420f/assessments/clawgui.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 4155c4340e1b7a5ca09b5decae990b0a6948420f\">4155c43 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-09-26T09:09:13+03:00\"><th scope=\"row\"><a href=\"https://github.com/haorui-harry/agent-harness\" target=\"_blank\" rel=\"noopener\">Agent Harness</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-26\">2026-09-26</time></td><td class=\"review-ref\"><a href=\"https://github.com/haorui-harry/agent-harness/tree/109dde248cb44227a9ed3a204790432a6da843da\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 109dde248cb44227a9ed3a204790432a6da843da\">109dde2 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: transform an open-ended user request into concrete workspace/tool/evidence actions and a delivered artifact through a persistent thread execution whose operational plan can be model-selected and revised from execution feedback. - Disturbance / variety regulated: heterogeneous user goals, available capabilities, current workspace state, tool/evidence results, failed or missing artifacts/validation, and changing completion gaps during the run. - Decisive decision or feedback right: in live-enabled mode, choose the substantive task-graph actions to perform and revise those actions after observing current execution state and completion gaps. - Decision owner: the configured live model actor reached through first-party task-profile expansion/subagent/replan prompts. - Supporting / enforcement mechanisms: HarnessEngine, task-profile compiler, executable graph/dependencies, TaskGraphActionMapper, tool/skill registries, persistent thread/workspace state, command/tool execution, safety constraints and model-call budgets. - Closure path: user request → thread/profile/graph context → live model selects operational graph additions/actions → runtime executes tools/workspace/subagent work → results/artifacts/world state enter noderesults/completion state → live replan can select additional actions → final synthesis/delivery reflects the changed operational state. - Boundary reachability: ThreadFirstSuperAgent.run() is a shipped standard entrypoint; it invokes compilegenerictaskpayload(...), passes the supported livemodel configuration, and executes the resulting graph through the credited thread runtime without requiring an adjacent development/evaluation system. - Why this is / is not agent-owned: removing the live model from the live-enabled mode removes the discretionary task-specific choice of model-generated graph additions/replan actions; deterministic fallback machinery remains, but it does not make materially the same open-ended decisions with the same discretion. - Evidence: app/harness/superagent.py; app/harness/taskprofile.py; app/agents/taskactions.py; app/agents/runtime.py. - Basis: explicit + structural - Confidence: high - Caveats: no-key mode has substantially more deterministic planning. A is credited to the supported live-enabled first-party operating mode, not to every execution configuration.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party S2 coordination function is established at the declared boundary. - Disturbance / variety regulated: candidate disturbances inspected included concurrent subagent/shared-workspace interference, skill-output conflict/redundancy, graph scheduling dependencies and parallel mission-track execution. - Decisive decision or feedback right: not established for a specific disturbance among distinct S1 operational units. - Decision owner: not applicable. - Supporting / enforcement mechanisms: task-graph dependency ordering, sequential skill execution, complementarity/conflict scoring, conflict/consensus reports, persistent shared thread state, and the optional parallel execution helper. - Closure path: no qualifying disturbance → coordination response → subsequent S1 behavior loop was found. - Why this is / is not agent-owned: ownership is not classified because the S2 function itself is not established. - Evidence: app/agents/subagents.py; app/main.py; app/routing/complementarity.py; app/routing/executor.py; app/graph.py. - Basis: structural negative -\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: regulate the currently executing job as a whole when present commitments no longer close the task, by deciding which additional operational commitments should be inserted before delivery. - Disturbance / variety regulated: missing required artifacts/channels/validation, command or tool failure, evidence/workspace gaps, incomplete current execution, and mismatches between the task specification and observed world state. - Decisive decision or feedback right: choose new current commitments from workspaceaction, toolcall, and subagent actions after seeing whole-job execution/completion state, and insert those commitments into the active graph. - Decision owner: the configured live model actor in livereplansuggestions() for the live-enabled mode. - Supporting / enforcement mechanisms: deterministic task/world-state construction, failure-policy classification, capability registry suggestions, fallback repair seed, node allow-lists, graph mutation, dependency rewiring, persistent execution state, scheduler/recovery machinery and tool/workspace enforcement. - Closure path: current graph executes → completion packet/world state exposes unresolved gap → graphreplan receives current job state → live model selects additional commitments → runtime appends the selected nodes and rewires synthesis/completion dependencies → subsequent execution performs the added work before the job can close. - Boundary reachability: the standard task-profile compiler adds a first-party graphreplan node whenever graph expansion enables replanning, and the standard thread-first execution path reaches TaskGraphActionMapper.executegraphreplan; supported livemodel configuration is carried through the same runtime context. - Why this is / is not agent-owned: without the live model, the runtime can still apply deterministic fallback/capability repairs, but it no longer makes the same task-specific discretionary choice among allowed new commitments. The model therefore owns the open-ended current-control decision in the credited mode; the runtime enforces and persists it. - Evidence: app/harness/taskprofile.py; app/agents/taskactions.py; app/agents/runtime.py; app/harness/superagent.py; tests/testagentruntime.py as corroboration. - Basis: explicit + structural - Confidence: high - Caveats: S3 is mode-dependent; the autonomous owner exists in live-model-enabled execution. Deterministic recovery/scheduling alone would not justify A. - Whole-system current view: replan input includes query/graph id, failure policy, completion packet, stategap, capability replan, accumulated noderesults, execution-loop schema, current loop phase, phase summary and fallback seed; this is a job-wide current-state view rather than one worker&#39;s local result. - Current-control decision scope: add or withhold new tool calls, workspace actions and bounded subagent commitments, and thereby alter the active graph dependencies that gate synthesis/completion.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no sufficiently independent complementary operational-audit path is established in the standard distribution. - Disturbance / variety regulated: candidate audit surfaces inspected included the live critique pass, structured dissent/conflict verification, completion/validation nodes, traces, red-team/evaluator utilities, tests and report artifacts. - Decisive decision or feedback right: no complementary audit judgment with materially different access to operational reality is closed at the assessed runtime boundary. - Decision owner: not applicable. - Supporting / enforcement mechanisms: critique prompts, evidence digest, deterministic conflict/dissent checks, validation artifacts, traces and development/evaluation utilities. - Closure path: not established for an independent audit channel. - Why this is / is not agent-owned: ownership is not classified because the S3 function itself is not established. - Evidence: app/harness/liveagent.py; app/graph.py; app/routing/executor.py; adjacent tests/ and evaluator/red-team surfaces. - Basis: structural negative -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no organizational outside-and-then adaptation loop is established at the assessed deployment boundary. - Disturbance / variety regulated: candidate surfaces inspected included external evidence/search, runtime learning statistics, optimizer runs, live experiments, research-lab comparisons, strategy selection and skill reliability feedback. - Decisive decision or feedback right: no first-party path was found that turns external/future-relevant distinctions into organizational adaptation options and returns those options into present harness capability. - Decision owner: not applicable. - Supporting / enforcement mechanisms: evidence providers, recordrun learning statistics, reliability-aware skill selection, optimizer/experiment result stores and research-lab tooling. - Closure path: not established. - Why this is / is not agent-owned: ownership is not classified because the S4 function itself is not established. - Evidence: app/memory/learning.py; app/routing/complementarity.py; app/harness/optimizer.py; app/harness/iteration.py; evidence/search paths in app/harness/evidence.py. - Basis: structural negative -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no runtime identity/ultimate-policy closure is established at the chosen recursion. - Disturbance / variety regulated: candidate surfaces inspected included system modes, risk/governance policy bundles, human approval/interrupt controls, constraints, recipes and static runtime settings. - Decisive decision or feedback right: no first-party path was found for resolving an identity- or ultimate-policy-level issue and returning that authoritative decision to govern subsequent operation. - Decision owner: not applicable. - Supporting / enforcement mechanisms: static PolicyBundle values, runtime constraints, safety checks, approval flags, operator interrupt/resume and configuration. - Closure path: not established. - Why this is / is not agent-owned: ownership is not classified because the S5 function itself is not established. - Evidence: app/policy/center.py; runtime constraints/settings in app/harness/models.py and app/harness/runtimesettings.py; thread control in app/agents/runtime.py. - Basis: structural negative -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/f2b0fec6e23af8b058420f9cbad438f21ebcc4ab/assessments/haorui-agent-harness.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit f2b0fec6e23af8b058420f9cbad438f21ebcc4ab\">f2b0fec &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-09-19T18:54:33+03:00\"><th scope=\"row\"><a href=\"https://github.com/open-multi-agent/open-multi-agent\" target=\"_blank\" rel=\"noopener\">OMA / Open Multi-Agent</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-19\">2026-09-19</time></td><td class=\"review-ref\"><a href=\"https://github.com/open-multi-agent/open-multi-agent/tree/4107fb144653c3240c569f345cf06b028dd7747a\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 4107fb144653c3240c569f345cf06b028dd7747a\">4107fb1 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously execute assigned goals/tasks against model/tool environments and produce operational outcomes for the caller/run. - Disturbance / variety regulated: heterogeneous prompts and task requirements, model responses, tool/API results, dependency payloads, context state, structured-output failures and external-backend results requiring context-sensitive next actions. - Decisive decision or feedback right: choose the next model-mediated action within a task — respond, invoke an allowed tool, consume observations, continue reasoning/delegation where enabled, and settle the task result. - Decision owner: the active OMA built-in LLM worker agent for standard built-in-agent modes; external process/ACP workers own their private inner loops and are not imported as first-party OMA decision actors. - Supporting / enforcement mechanisms: Agent runner, model adapters, tool registry/grants, AgentPool, task queue, dependency/context injection, shared memory, budgets/timeouts, checkpoints and run-store fencing. - Closure path: task/prompt + current context → agent model selects action/tool → runtime executes/returns observation → observation re-enters agent context → agent selects further action or final result → task/run settlement and dependent release. - Boundary reachability: runAgent, runTasks and runTeam with built-in agents are first-party documented @open-multi-agent/core operating modes, not examples or CI-only paths. - Why this is / is not agent-owned: removing the model-driven worker while leaving the scheduler, queue, stores, approval machinery and tool executor leaves no actor that makes the contextual task-level operational choices. Runtime machinery constrains and persists those decisions but does not substitute for them. - Evidence: packages/core/README.md, README.md, task-scheduling.md. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party S2-specific coordination loop was established for a concrete interference/oscillation among distinct OMA S1 worker units at the declared run/team recursion. - Disturbance / variety regulated: candidate disturbances inspected included parallel ready tasks, competition for AgentPool capacity, duplicate processes advancing one logical run, dependency ordering and shared-memory writes. - Decisive decision or feedback right: no qualifying S2-specific autonomous coordination discretion is supplied. Scheduler assignment/load balancing is whole-run resource/commitment control; run-store fencing prevents duplicate ownership of the same run; dependency edges sequence work; namespaced shared memory avoids key collisions. - Decision owner: none established for S2 in the standard distribution. - Supporting / enforcement mechanisms: AgentPool semaphore, task dependencies, event-driven ready set, least-busy/composite scheduling, namespaced shared memory, run-store lease/fencing and deterministic task-status propagation. - Closure path: no first-party S2-specific feedback loop was found that observes an interaction disturbance among independent S1 workers and changes their subsequent local behaviour to damp it. - Why this is / is not agent-owned: multiple agents and parallel branches exist, but task assignment, dependency sequencing and capacity limits are not S2 merely because they coordinate execution. The reviewed mechanisms map more directly to S3 resource/current-control or duplicate-execution safety and do not expose an S2-specific autonomous decision path. - Evidence: task-scheduling.md, scheduler.ts, run-store.md, shared-memory.md. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3 / regulation: - State: C - Function: regulate current whole-run commitments and interventions after operational outcomes reveal that the pending task graph should change. - Disturbance / variety regulated: task failure, consensus rejection, successful outcomes that invalidate/reshape downstream work, assignee infeasibility and remaining budget/commitment constraints while other pending/blocked work still exists. - Decisive decision or feedback right: choose whether to keep the current pending graph or propose a PlanPatch that adds replacement tasks, retargets pending tasks or supersedes pending branches in response to a current task outcome. - Decision owner: OMA does not supply the autonomous decisive replanner. The developer/application supplies a Replanner or onTaskOutcome actor; that actor may itself call an LLM/service, but such autonomous composition remains application-owned. OMA owns validation, atomic application and execution closure after a proposal exists. - Supporting / enforcement mechanisms: TaskOutcome snapshot of complete current task state and remaining budgets, deterministic Scheduler and AgentSelector, recovery limits, DAG validation, optional onPlanPatch gate, checkpoint persistence and event-driven publication of newly-ready work. - Closure path: task settles/reaches verification outcome → OMA constructs whole-run TaskOutcome → composed replanner proposes patch → OMA validates/gates and atomically applies accepted current-control changes → new/retargeted pending work enters the same scheduler and changes subsequent execution. - Whole-system current view: TaskOutcome.tasks exposes the full current task list together with current plan revision, triggering task/result/verification and remaining budget dimensions; scheduler decisions also inspect current DAG/load state. - Current-control decision scope: pending commitments may be appended, retargeted to another eligible agent, or superseded, thereby changing who will perform current work and which remaining commitments still count toward the run. - Boundary reachability: repairable recovery, Replanner, onTaskOutcome, PlanPatch validation and atomic application are documented first-party @open-multi-agent/core runtime surfaces reachable in runTasks/team execution; the missing element is the developer-composed decisive actor, which is why the state is C, not A. - Why this is / is not agent-owned: deterministic scheduling already enforces current assignment/criticality/load policy, but no shipped autonomous actor owns the discretionary replan judgment. The first-party recovery seam is S3-specific and operationally closes a composed decision back into current execution, satisfying the narrow constructor threshold without pretending the scheduler itself is an autonomous S3 owner. - Evidence: adaptive-recovery.md, recovery.ts, task-scheduling.md, scheduler.ts. - Basis: explicit - Confidence: high - Caveats: the ordinary one-shot coordinator is not this S3 owner; it is explicitly absent mid-run. Durable plan/dispatch approval can constrain current work but OMA deliberately leaves reviewer product/transport/authorization to the integrator, so no separate parent-governed S3 mode is published here.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: independently challenge a proposed operational result and feed an audit judgment back into the result/control path before downstream use. - Disturbance / variety regulated: plausible but incorrect/incomplete task answers whose ordinary worker completion path would otherwise become accepted downstream state without an independent challenge. - Decisive decision or feedback right: independent judge agents decide accept/dissent against the original question and proposed answer; quorum and configured dissent policy determine whether the result is accepted, rejected or returned to the proposer for revision. - Decision owner: the configured OMA judge-agent roster owns the audit judgments; deterministic quorum parsing/aggregation and runtime gating transport those judgments. On onDissent: &#39;revise&#39;, the proposer remains the operational actor producing the corrected candidate, while judges retain the complementary audit right. - Supporting / enforcement mechanisms: runConsensus, per-task verify, separate judge invocations, structured {accept, critique} verdicts, quorum/max-round controls, dissent persistence, token/cost accounting, shared-memory verdict records and task-output replacement after an accepted revision. - Closure path: worker/proposer produces candidate → separate judges receive original question + candidate and issue verdicts/critiques → quorum/dissent policy resolves audit → dissent can be fed back to proposer for another round → an accepted revised answer supersedes task output and is propagated into queue/shared memory/downstream results. - Claim being audited: that the proposer/worker&#39;s candidate adequately answers the original task/question and should be accepted as the task result. - Ordinary reporting path: the worker/proposer&#39;s own final answer/result through the ordinary task completion path. - Complementary access path: distinct judge-agent invocations independently evaluate the candidate against the original question under refute or differentiated-lens prompts; they are not the worker&#39;s ordinary completion check and can use separately configured models/agents. - Independence boundary: judge agents are a separately configured verifier roster, invoked after/around the proposer result with their own model calls and structured verdict contract; they receive the candidate rather than inheriting the proposer&#39;s hidden reasoning state. Different judges can use different models and lens framings. The classification does not rely on generic traces, governance receipts or the post-run evaluation subsystem. - Who acts on findings: the first-party consensus loop aggregates judge decisions; under the default revise policy it returns dissent to the proposer, and per-task verification replaces downstream task state only when a revised candidate is accepted. - Boundary reachability: runConsensus() is a documented top-level core runtime mode and verify is a documented per-task hook in runTasks/runTeam; both are shipped first-party runtime paths rather than CI/eval-only machinery. - Why this is / is not agent-owned: removing the judge agents while leaving quorum code, traces and result plumbing removes the substantive independent audit judgments. Deterministic parsing and quorum enforcement cannot recreate critiques or accept/dissent decisions, so the decisive S3 feedback is agent-owned. - Evidence: consensus.md, coordinator.md, packages/core/README.md. - Basis: explicit - Confidence: high - Caveats: governance-floor receipts and journal verification are useful audit mechanisms but are not the reason for A; post-run evaluation explicitly does not alter the business result. The positive mapping is the independent judge loop with corrective return.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no first-party runtime path was established that senses external/future-relevant change, develops adaptation options and returns a strategic capability change into present OMA operation. - Disturbance / variety regulated: candidate S4 inputs inspected included provider/tool failures, task outcomes, evaluation regressions/trends, routing profiles, model/provider choices and changing external requirements. - Decisive decision or feedback right: no runtime S4 adaptation judgment is supplied. Adaptive recovery changes the current unexecuted graph in response to current task outcomes (S3-constructor scope), while the evaluation subsystem measures completed runs without changing their business result. - Decision owner: none established for S4 in the assessed runtime boundary. - Supporting / enforcement mechanisms: offline/online evaluation reports and gates, model/execution routing, adaptive recovery, configuration, callbacks, provider fallback and application-owned policy code. - Closure path: no supported first-party outside/prospective sensing → option-generation → adaptation-decision → changed present capability loop was found inside the product-runtime boundary. - Why this is / is not agent-owned: evaluation can expose versions, regressions and trends, but its documented contract is observe-only relative to business runs; using its reports to change prompts/models/topology in CI or operator practice is an adjacent application/development loop unless separately wired by the integrator. - Evidence: evaluation.md, adaptive-recovery.md, packages/core/README.md. - Basis: explicit -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party runtime identity/ultimate-policy escalation-decision-return loop was established at the OMA run/team recursion. - Disturbance / variety regulated: candidate policy matters included declared governance roles, consequential-tool rules, egress policy, approval decisions, role/tool boundaries, budget ceilings and explicit topology overrides. - Decisive decision or feedback right: no autonomous or operationally closed first-party parent authority resolves identity/ultimate-policy disputes for the system. Applications declare governance intent, tool grants, egress/budget policy and reviewer integration before/around execution. - Decision owner: application/developer/organization outside the assessed runtime owns ultimate policy; OMA deterministically validates/enforces selected rules and records deviations. - Supporting / enforcement mechanisms: governanceIntent/required roles/order, execution receipts and governanceConclusion, consequential-tool classification/confirmation, egress policy, tool allow/deny lists, budgets, durable approval ledger, run-store cancellation and configuration. - Closure path: configured constraints and approval decisions can change/stop subsequent execution, but no first-party standard path carries an identity/ultimate-policy issue to a legitimate ultimate authority and returns that authority&#39;s decision as S5 closure. - Why this is / is not agent-owned: governance receipts prove that declared roles/order executed; they do not decide what the organization&#39;s identity or ultimate policy should be. Durable approvals bind exact reviewed content but OMA deliberately provides no reviewer product, routing, RBAC or escalation layer. These are strong enforcement/governance primitives without an S5 decision owner. - Evidence: tool-configuration.md, durable-approvals.md, observability.md. - Basis: explicit - Confidence: high - Caveats: an organization can build a legitimate parent-policy layer on top of the durable approval/governance primitives; Methodology 0.3.5 does not publish S5 merely because a human can approve an operational action or because policy text is enforceable.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/b4ce8b5a5cb50fb5ea1941fc7e0a2e73781ec6ea/assessments/open-multi-agent.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit b4ce8b5a5cb50fb5ea1941fc7e0a2e73781ec6ea\">b4ce8b5 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"4\" data-assessment-at=\"2026-09-24T20:12:57+00:00\"><th scope=\"row\"><a href=\"https://github.com/agentwasp/agentwasp\" target=\"_blank\" rel=\"noopener\">WASP</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>4</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-24\">2026-09-24</time></td><td class=\"review-ref\"><a href=\"https://github.com/agentwasp/agentwasp/tree/8282a76f57aa4d0b7f2071321f064b26be942024\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 8282a76f57aa4d0b7f2071321f064b26be942024\">8282a76 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously execute operator objectives through an iterative model/tool loop and bounded goal runtime that can absorb tool/environment results and choose subsequent operational action. - Disturbance / variety regulated: request ambiguity, tool/API/file results, failed skill calls, changing goal/task state, external data and intermediate observations that alter the next useful action. - Decisive decision or feedback right: choose model-driven skill calls and subsequent action/recovery across the LLM loop, and for autonomous goals generate and execute task plans within the configured repertoire. - Decision owner: the model-driven WASP operational agent/goal actor. - Supporting / enforcement mechanisms: intent fast paths, Context Builder, SkillExecutor, model manager, GoalOrchestrator, deterministic validators/guards, budgets, persistence, tool adapters and retry limits. - Closure path: operator/autonomous objective enters the runtime → model chooses skills/actions → first-party executor runs them → observations/errors return to model/goal state → model continues, replans where applicable or completes → result returns to the operator/environment. - Boundary reachability: the model/skill loop and Goal Engine are first-party standard operating surfaces documented and wired by the shipped agent-core runtime. - Why this is / is not agent-owned: deterministic routing, limits and post-response guards constrain the loop, but substantive ordinary skill/action choices and goal planning are made by model inference rather than by those enforcement mechanisms. - Evidence: execution-pipeline.md; goalorchestrator/orchestrator.py. - Basis: explicit + structural - Confidence: high - Caveats: fast paths and final validators can deterministically handle or constrain some requests. The A claim is based on the standard model-driven execution/goal path, not on every possible fast path being agent-owned.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: attenuate interference among multiple persistent autonomous agents that share finite model, token, CPU and execution capacity in one WASP deployment. - Disturbance / variety regulated: simultaneously RUNNING agents can collectively monopolize model/provider capacity, exceed the global token budget, overload CPU or create excessive concurrent steps, degrading other S1 units despite each unit being locally valid. - Decisive decision or feedback right: choose/revise the cross-agent concurrency, shared-token and load-throttling regime that determines when an S1 may take its next step under shared pressure. - Decision owner: no autonomous standard-mode S2 owner is packaged. AgentOrchestrator deterministically enforces configured limits; the model-driven MetaSupervisor that could own richer team coordination is disabled by default and explicitly described as research-only at this revision. - Supporting / enforcement mechanisms: asyncio.Semaphore across agent steps, global Redis token counter, CPU threshold, active-agent store, shared model manager and deterministic throttling events. - Closure path: multiple S1 agents request/take ticks → shared concurrency/token/CPU conditions are evaluated → over-capacity work is deferred/throttled or serialized → capacity/next window becomes available → affected agents resume later. - Boundary reachability: shared throttles are wired directly into the standard AgentOrchestrator.tick() path used by persistent agents; no adopter-defined transport is needed for the coordination relation. - Why this is / is not agent-owned: the inter-S1 disturbance and attenuation path are explicit, but the decisive regime is static/configured and mechanically enforced. An autonomous coordination actor would have to be composed/enabled beyond the credited standard mode, so the state is C, not A. - Evidence: agentmanager/orchestrator.py; agent-orchestration.md; config.py. - Basis: explicit + structural - Confidence: high - Caveats: Plan Critic is not credited as S2 because validating one goal plan does not regulate interference among distinct S1 units. The disabled MetaSupervisor corroborates a richer possible pattern but does not upgrade the credited runtime mode. - Distinct S1 units: two or more persistent autonomous AgentRuntime instances with separate objectives, goal queues and execution contexts hosted by the same AgentOrchestrator. - Inter-S1 disturbance: these agents share model infrastructure, CPU and global token/step capacity, so aggregate activity can starve or overload peers even when no individual agent violates its own goal semantics. - Attenuating coordination relation: the orchestrator serializes/bounds simultaneous agent steps, stops all new agent ticks when the global token budget is exhausted and skips ticks under CPU overload. - Feedback into subsequent S1 behaviour: throttled agents do not take the current step; once the semaphore/window/load permits, a later tick re-enters their runtime and their next operational action occurs. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the credited mechanism exists specifically to regulate contention created by multiple autonomous agents sharing finite resources, not merely to pass messages or assign subtasks.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3 / regulation: - State: C(P) - Function: maintain an organization-wide current view of operational pressure/commitments and intervene in current autonomous activity through aggregate throttling or parent supervisory controls. - Disturbance / variety regulated: excessive active-goal pressure, recent operational error rate, high latency, runaway memory growth, CPU saturation, resource-cap exhaustion and current agent commitments that should be paused/resumed on behalf of the whole deployment. - Decisive decision or feedback right: determine which current organizational activity is allowed to proceed under aggregate pressure and, in the parent mode, decide which persistent agents remain active, paused or resumed after reviewing current organization state. - Decision owner: base C mode — deterministic CPI/Resource Governor/AgentOrchestrator rules execute configured current-control responses with no autonomous S3 owner. Parent P mode — the single self-hosting operator owns supervisory pause/resume/archive decisions through the first-party all-agent dashboard. - Supporting / enforcement mechanisms: CPI component collectors and agent:cpihigh; Resource Governor counters/caps; AgentOrchestrator status persistence; dashboard all-agent snapshot showing status, active goals and cognitive budgets; scheduler jobs that honor CPI gating. - Closure path: current whole-system pressure/status is gathered → base deterministic controls gate background/current work, or the parent operator reviews the all-agent snapshot and chooses pause/resume/archive → AgentOrchestrator persists the new status/removes or recreates runtime state → subsequent ticks follow the changed current-control decision. - Boundary reachability: CPI/governor controls are wired into standard scheduler/runtime operation, while the all-agent dashboard and pause/resume/archive endpoints are shipped first-party operator surfaces over the same AgentOrchestrator. - Why this is / is not agent-owned: WASP has concrete whole-system current-control structure, but the base current-control judgments are configured thresholds rather than model-owned discretion. The operator dashboard supplies a separately closed parent supervisory mode, hence C(P) rather than A. - Evidence: agent/cpi.py; scheduler/cpimonitor.py; resource-governor.md; dashboard/routes/agents.py; agentmanager/orchestrator.py. - Basis: explicit + structural - Confidence: high - Caveats: per-goal replanning is local S1/current-task recovery, not whole-system S3 by itself. Parent credit relies on the all-agent status/budget view plus operative pause/resume closure, not merely on a generic human edit or stop button. - Whole-system current view: CPI combines active-goal count, recent error rate, latency, memory growth and CPU; the dashboard separately lists every persistent agent with current status, active-goal count/IDs and cognitive-budget usage. - Current-control decision scope: base rules gate background autonomous/perception/dream work and enforce shared operational caps; the parent can remove an agent from active operation by pausing/archiving it or restore it with resume, changing current commitments represented in subsequent ticks.\">C(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: challenge WASP&#39;s ordinary self-model and epistemic claims with materially different direct operational evidence and return discrepancies into subsequent control/state. - Disturbance / variety regulated: the agent can believe it has strengths or domain confidence that no longer match actual observed skill outcomes, while silent cognitive subsystems or recent error spikes can remain invisible in the self-model&#39;s ordinary narrative. - Decisive decision or feedback right: judge whether claimed strengths/confidence are contradicted by direct skill success rates, audit-log outcomes or missing cognitive heartbeats and decide which self-model/epistemic corrections follow. - Decision owner: the standard distribution supplies the full complementary evidence and corrective path, but the decisive audit judgment is encoded in deterministic thresholds/rules in SelfIntegrityMonitorJob; no autonomous auditor owns that judgment in the credited mode. - Supporting / enforcement mechanisms: direct SQL reads from auditlog and cognitive-system tables, Redis self-model/epistemic state, success-rate thresholds, drift threshold, report persistence, automatic self-model removal/epistemic correction and improvement queueing. - Closure path: ordinary self-model/epistemic claims persist → scheduled monitor independently reads raw operational success/error/heartbeat evidence → threshold comparisons produce findings → unsupported strengths are removed, epistemic confidence is corrected and improvement work can be queued → later reasoning uses the corrected state. - Boundary reachability: SelfIntegrityMonitorJob is imported and registered by the standard runtime and the default configuration exposes integritymonitorenabled=true; its evidence and correction stores are the same first-party runtime stores used by live cognition. - Why this is / is not agent-owned: the complementary access and feedback closure are real, but the audit judgment is deterministic rather than an autonomous agent&#39;s discretionary independent assessment. That is a function-specific constructor path (C), not A. - Evidence: scheduler/integrity.py; configuration.md. - Basis: explicit + structural - Confidence: high - Caveats: Plan Critic and final ResponseValidator are not used as the positive S3 witness because they are routine checks inside the production path rather than complementary access to operational reality. - Claim being audited: self-model assertions of strengths and epistemic confidence, plus the implicit claim that core cognitive producers are operating normally. - Ordinary reporting path: agent:selfmodel, agent:epistemic and ordinary runtime/cognitive state describe what WASP believes about its capability and confidence. - Complementary access path: SelfIntegrityMonitorJob reads measured skill success/failure data, recent auditlog anomalies and direct DB/Redis heartbeat evidence from the cognitive producers rather than relying on those self-claims. - Independence boundary: the scheduled monitor is separate from the model process that creates/uses the self-model and checks alternative operational records; however its verdict logic remains deterministic and therefore does not establish autonomous audit ownership. - Who acts on findings: first-party monitor actuators remove invalid strengths, overwrite drifted epistemic confidence and queue improvement items; the corrected state then affects subsequent cognition/operation.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:4\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A - Function: convert explicit environmental/user correction signals into prospective behavioral adaptation that changes how future WASP operation reasons and acts. - Disturbance / variety regulated: user corrections reveal that current behavior is systematically wrong — for example hallucination, inappropriate refusal, wrong-skill choice or missing-context handling — and repetition of that behavior would degrade future viability with the operator/environment. - Decisive decision or feedback right: interpret the correction context, formulate the durable future-facing rule/few-shot/anti-pattern that should prevent recurrence and admit that adaptation into active behavioral memory. - Decision owner: the model-driven BehavioralLearnerJob owns semantic rule extraction; deterministic safety filtering/deduplication/storage constrain and persist the result. - Supporting / enforcement mechanisms: correction-pattern detection, Redis pending queue, two-minute scheduler, adversarial-rule filter, behavioral-rules DB, dedup/conflict checks, future prompt injection and notification surfaces. - Closure path: user/environment correction is detected → exchange is queued → scheduled LLM analyzes the failure and generates a behavioral adaptation rule → safe active rule is persisted → Context Builder injects active learned rules/few-shots into future system prompts → subsequent S1 behavior operates under the adaptation. - Boundary reachability: Behavioral Learning is documented as default-enabled, registered in main.py, and its stored active rules are consumed by the standard prompt builder; no downstream learner or manual prompt edit is required. - Why this is / is not agent-owned: the semantic choice of what future behavior should change is produced by an autonomous model call. The queue, filters and database only transport/constrain that adaptation judgment, so the decisive S4 option-generation right is agent-owned. - Evidence: behavioral-learning.md; scheduler/behaviorallearner.py; memory/behavioral.py; configuration.md. - Basis: explicit + structural - Confidence: high - Caveats: generic memory, current-goal replanning and Skill Evolution are not needed for this mapping. The Opportunity Engine is also not credited as a parent S4 mode because, at the pinned ref, its dashboard accepted endpoint only changes status; the documented action-execution closure is not present in the inspected route. - External distinction: a user correction is a first-party captured environmental distinction about how the running organization failed to meet operator expectations; the learner retains the request, bad response and explicit correction context. - Future / prospective distinction: the LLM is asked what rule the agent should follow to avoid the error in future interactions, turning the observed correction into a forward-looking behavioral distinction rather than merely recording the past event. - Adaptation option generated: a typed behavioral rule plus optional skillpoison and dynamic few-shot pair describing the changed future response/skill policy. - Path back into current capability / S3: accepted-safe rules are saved active and injected into every later system prompt, directly modifying the operating repertoire used by subsequent S1 decisions; operator/dashboard surfaces can deactivate bad rules if needed.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S5 / identity: - State: C(P) - Function: maintain and revise the WASP organization&#39;s explicit identity, purpose/autonomy posture and ultimate operating principles, with a dedicated constructor path and a separately closed single-operator parent mode. - Disturbance / variety regulated: changes or disputes about what the agent is for, how autonomous it should be, confirmation/risk posture, proactive behavior and other identity-level directives that should govern subsequent operation rather than one ordinary task. - Decisive decision or feedback right: authoritatively choose the current identity prompt (or restore a prior/default identity) that defines purpose/autonomy/policy posture for future model operation. - Decision owner: base C mode — IdentityManager exposes an identity-specific save/version/rollback/injection path but no autonomous ultimate-policy actor is wired to own it. Parent P mode — the single deployment operator owns the authoritative identity decision through the first-party dashboard. - Supporting / enforcement mechanisms: Redis identity prompt/compiled state, version history, prompt compilation of autonomy/confirmation/risk/proactive directives, dashboard save/reset/rollback API, audit logging and Context Builder identity injection. - Closure path: identity/policy issue reaches the identity constructor or operator dashboard → a new/default/prior identity is selected → IdentityManager saves/compiles/version-controls it → subsequent prompt construction injects the active identity/directives → later S1 behavior is governed by the returned decision. - Boundary reachability: IdentityManager is initialized by the standard runtime and passed into prompt construction; dashboard identity routes call its live save/reset/rollback methods. Both constructor and parent paths are first-party surfaces of the assessed self-hosted deployment. - Why this is / is not agent-owned: WASP intentionally supplies a function-specific identity decision/return primitive, supporting C, but does not wire an autonomous agent as legitimate ultimate identity authority. The standard closed authority is the deployment&#39;s single operator, supporting (P) rather than A. - Evidence: identity/manager.py; dashboard/routes/identity.py; agent/context.py; configuration.md. - Basis: explicit + structural - Confidence: high - Caveats: prime.md, safety guards and ordinary task approvals are not independently treated as S5. Parent credit rests specifically on the Identity Engine&#39;s identity-level authoring/version/return path. Self-improvement of implementation code is not assumed to grant autonomous ultimate-policy authority. - Identity / ultimate-policy issue: the DEFAULTPROMPT explicitly states the organization&#39;s identity/purpose, autonomous operating mode and governing principles; IdentityManager compiles materially identity-level properties such as autonomy, confirmation threshold, risk tolerance and proactivity. - Ultimate authority in each claimed mode: base C exposes the identity-specific decisive path but leaves legitimate autonomous authority to a downstream composition; parent P assigns authoritative selection to the self-hosting single operator through the dashboard identity editor/reset/rollback controls. - Return-to-operation path: operator/constructor decision → IdentityManager.save/reset/rollback → active prompt + compiled identity cache/Redis state → formatforprompt/Context Builder injection → subsequent model decisions operate under the selected identity.\">C(P)</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c62efc8a5ab1194f3af914371786771519632c81/assessments/wasp.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c62efc8a5ab1194f3af914371786771519632c81\">c62efc8 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-09-21T00:27:46+03:00\"><th scope=\"row\"><a href=\"https://github.com/RightNow-AI/openfang\" target=\"_blank\" rel=\"noopener\">OpenFang</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-20\">2026-09-20</time></td><td class=\"review-ref\"><a href=\"https://github.com/RightNow-AI/openfang/tree/acf2587e46be174c10200489c9a2d23a39a98aeb\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision acf2587e46be174c10200489c9a2d23a39a98aeb\">acf2587 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously perform assigned work through a first-party model/tool decision-action loop and persistent Hands. - Disturbance / variety regulated: task ambiguity, tool/environment observations, changing external information, tool failures/results and uncertainty over the next operational action. - Decisive decision or feedback right: choose the next substantive tool/action from current context and observations and decide whether to continue or conclude. - Decision owner: the running OpenFang agent/Hand model. - Supporting / enforcement mechanisms: kernel lifecycle, tool runner, memory/session substrate, context guards, loop guard, provider retry/fallback, scheduler, capability checks, channels and sandboxing. - Closure path: task/message → model decision → OpenFang executes selected tool/action → observation returned into conversation → next model decision → repeated operation or terminal outcome. - Boundary reachability: runagentloop is the standard first-party runtime path and bundled agents/Hands directly use that runtime in the shipped distribution. - Why this is / is not agent-owned: the kernel transports, bounds and enforces decisions, but the model selects substantive actions from current evidence; removing the model leaves only deterministic runtime machinery rather than materially the same operational choice. - Evidence: crates/openfang-runtime/src/agentloop.rs, crates/openfang-hands/bundled/, README.md. - Basis: explicit + structural. - Confidence: high. - Caveats: external LLM providers supply inference but do not own OpenFang&#39;s first-party operating loop/closure.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no sufficiently evidenced S2-specific attenuation of concrete interference/conflict/oscillation among distinct OpenFang S1 units is established in the reviewed standard distribution. - Disturbance / variety regulated: no specific qualifying inter-S1 disturbance is established. - Decisive decision or feedback right: none established for an S2-specific attenuation relation. - Decision owner: none established for S2. - Supporting / enforcement mechanisms: message bus, agentsend, delegation, shared memory, workflow sequencing, fan-out/collect, capability restrictions and task queues. - Closure path: no qualifying inter-S1 disturbance → attenuation relation/decision → changed subsequent S1 behaviour loop is established. - Why this is / is not agent-owned: OpenFang supplies substantial communication and orchestration, but delegation/routing/sequencing/shared state alone do not meet the Methodology&#39;s S2 function threshold. - Evidence: agents/orchestrator/agent.toml, crates/openfang-runtime/src/toolrunner.rs, docs/workflows.md. - Basis: explicit absence after function-first review. - Confidence: high. - Caveats: a downstream workflow can define an actual organizational collision and use OpenFang primitives to regulate it; that separate system would require its own assessment.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: autonomously regulate current fleet composition and allocation of work across the OpenFang agent organization. - Disturbance / variety regulated: changing current task decomposition, available/running specialist agents, their capabilities/states and the need to allocate, add or remove operating capacity while work proceeds. - Decisive decision or feedback right: inspect the current fleet, choose specialist allocations via agentsend, create agents with agentspawn, terminate agents with agentkill, and synthesize current delegated work. - Decision owner: the shipped orchestrator model in the autonomous Orchestrator mode. - Supporting / enforcement mechanisms: agentlist state/capability data, kernel lifecycle/capability enforcement, inter-agent messaging, shared memory, tool timeouts and deterministic spawn/kill execution. - Closure path: current user/task demand + agentlist fleet view → Orchestrator model decides decomposition/allocation/fleet changes → kernel executes send/spawn/kill → affected specialists operate → their returned results/current state inform synthesis and later control decisions. - Boundary reachability: the Orchestrator is a bundled first-party agent manifest in the standard distribution; its required collaboration tools are first-party kernel/runtime tools. - Why this is / is not agent-owned: the model owns the discretionary choice of how to decompose and allocate current work and whether capacity should be spawned/killed. Kernel checks enforce permissions but do not choose the organizational allocation. - Evidence: agents/orchestrator/agent.toml, crates/openfang-runtime/src/toolrunner.rs, docs/agent-templates.md. - Basis: explicit + structural. - Confidence: high. - Caveats: deterministic workflow engine scheduling is not the S3 owner. No (P) modifier is published because operator CLI/TUI controls were not sufficient on the reviewed evidence to reconstruct a distinct parent-governed whole-system S3 loop rather than administrative intervention controls. - Whole-system current view: agentlist exposes all running agents with state, capabilities/tools, description/tags and model, and the Orchestrator is instructed to inspect available agents before allocating work. - Current-control decision scope: current task decomposition/allocation, specialist selection, creation/removal of active agent capacity and inter-agent commitment routing.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no standard first-party independent audit path is established whose findings are obligatorily returned into corrective production operation. - Disturbance / variety regulated: hidden divergence between ordinary operational outputs and reality/security/quality can be inspected, but corrective audit closure is not established. - Decisive decision or feedback right: none established for a complete complementary audit→correction loop. - Decision owner: none established for S3 publication. - Supporting / enforcement mechanisms: bundled security-auditor, security-review/fact-check workflow examples, Merkle audit trail, logs, health events, triggers and diagnostics. - Closure path: reviewed examples produce audit/fact-check findings or reports, but no standard path requires those findings to modify the producing S1/current operation before completion. - Why this is / is not agent-owned: the security auditor is a separate model actor with complementary tools/evidence, but independence plus judgment alone is insufficient; the first-party examples terminate findings in variables/reports/summaries instead of closing corrective feedback into operations. - Evidence: agents/security-auditor/agent.toml, docs/workflows.md, README.md. - Basis: explicit absence after closure review. - Confidence: high. - Caveats: users can author a remediation workflow using the supplied audit specialist and workflow engine, but that downstream composition is not the standard closed S3 mode assessed here.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no prospective environment-facing adaptation loop is established that changes OpenFang&#39;s future organizational capability. - Disturbance / variety regulated: external signals, predictions, collected intelligence and changing system events are handled as operational inputs, not as a first-party capability-adaptation program. - Decisive decision or feedback right: none established for selecting and incorporating future capability/organizational adaptations. - Decision owner: none established for S4. - Supporting / enforcement mechanisms: Collector/Predictor Hands, web/research agents, persistent memory/consolidation, knowledge graph, triggers, agent spawning, skill registry and user/developer custom manifests. - Closure path: no standard external/prospective distinction → adaptation options → selected option → changed present capability/S3 loop is established. - Why this is / is not agent-owned: Hands may continuously monitor the environment and agents may retain knowledge or spawn current specialists, but those behaviours serve current domain outcomes. They do not autonomously redesign or extend OpenFang&#39;s later capability from prospective intelligence. - Evidence: crates/openfang-hands/bundled/collector/HAND.toml, crates/openfang-hands/bundled/predictor/HAND.toml, docs/workflows.md, README.md. - Basis: explicit absence after function-first review. - Confidence: high. - Caveats: agent spawning changes current fleet capacity and therefore supports S3; it is not by itself prospective S4 adaptation. Developer-created agents/skills are external construction.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no runtime identity or ultimate-policy authority loop is established at the OpenFang organization boundary. - Disturbance / variety regulated: permissions, manifests, security controls, provider settings and operator configuration govern ordinary operation rather than an identity/ultimate-policy dispute. - Decisive decision or feedback right: ultimate organizational identity/policy remains authored in manifests/configuration/operator choices; no autonomous or operationally closed parent S5 loop is established. - Decision owner: none established for S5 publication. - Supporting / enforcement mechanisms: capability system, signed manifests, sandboxing, security policies, credential handling, schedules, quotas, tool policy and operator/API configuration. - Closure path: no qualifying identity/ultimate-policy matter → ultimate authority decision → returned governance of subsequent operation loop is established. - Why this is / is not agent-owned: deterministic security and manifest policy strongly constrain agents but do not themselves make identity/ultimate-policy decisions. Operator configuration is not automatically a parent S5 mode. - Evidence: README.md, docs/security.md, docs/architecture.md. - Basis: explicit absence after function-first review. - Confidence: high. - Caveats: human operators/maintainers can change manifests, capabilities and configuration, but the reviewed standard distribution does not reconstruct an identity-level matter, legitimate ultimate authority and return-to-operation loop required for S5/P.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/ebfcad0082979c63eb8c42a63c1e5c9f0a213d8b/assessments/openfang.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit ebfcad0082979c63eb8c42a63c1e5c9f0a213d8b\">ebfcad0 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"2\" data-assessment-at=\"2026-09-22T17:11:59+03:00\"><th scope=\"row\"><a href=\"https://github.com/agentscope-ai/QwenPaw\" target=\"_blank\" rel=\"noopener\">QwenPaw</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>2</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-22\">2026-09-22</time></td><td class=\"review-ref\"><a href=\"https://github.com/agentscope-ai/QwenPaw/tree/8af8b6e31a837a0e19ee6c9fffaf1c6b44b5f9ec\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 8af8b6e31a837a0e19ee6c9fffaf1c6b44b5f9ec\">8af8b6e &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously execute configured conversational or scheduled objectives and close their outputs through QwenPaw-owned session, trace and delivery paths. - Disturbance / variety regulated: heterogeneous user/channel requests, scheduled objectives, changing workspace/memory context, tool/model responses and delivery conditions. - Decisive decision or feedback right: choose the substantive response/action sequence for an admitted objective under the configured model, context and tools. - Decision owner: the model actor reached through the QwenPaw workspace/runtime for the active configured agent. - Supporting / enforcement mechanisms: CronExecutor, workspace streamquery, session allocation, trace collection, tool guard, channel manager, scheduler/heartbeat plumbing and persistent workspace/context state. - Closure path: user/channel/timer trigger → QwenPaw request/session/context → model-owned operational decision → tool/response execution → trace/session persistence and channel delivery → later operation can consume the resulting state. - Boundary reachability: scheduled tasktype=agent jobs are an ordinary first-party CronExecutor path and invoke the same QwenPaw workspace runtime without a fresh user turn. - Why this is / is not agent-owned: the model actor makes the material operational choice; QwenPaw owns the trigger, context, governance and delivery closure. No external coding-agent or peer-agent autonomy is needed for the positive claim. - Evidence: src/qwenpaw/app/crons/executor.py; first-party workspace/runtime invocation reached by that executor; channel/session/trace closure in the same path. - Basis: explicit + structural. - Confidence: high. - Caveats: some configured backends or integrations can delegate externally; only QwenPaw-owned runtime closure is credited here.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: attenuate interference among distinct QwenPaw S1 operations that share a constrained upstream model-service quota. - Disturbance / variety regulated: concurrent and high-rate model starts across configured agents/connections/aliases that share one supplier quota and can saturate that common resource. - Decisive decision or feedback right: admit a start now, reject/ask it to retry later, or hold the shared scope in cooldown according to the aggregated quota state. - Decision owner: constructor-level first-party coordination mechanism (SharedLimiter); no autonomous coordinator owns discretionary S2 policy at this boundary. - Supporting / enforcement mechanisms: shared quota-scope aggregation, active-count tracking, per-minute start history, strictest shared limit selection, 429 busy responses, retry metadata and cooldown after upstream overload. - Closure path: sibling S1 operations contend for a shared model-service quota → Hub observes shared active/rate state → limiter attenuates starts/rejects/cooldown → subsequent S1 calls are admitted only under the returned coordination state. - Boundary reachability: the frozen package ships the Hub as a qwenpaw CLI subcommand; pyproject.toml publishes the hub extra and includes it in the supported full installation, while src/qwenpaw/hub/modelservice/limiter.py provides the shared limiter. - Distinct S1 units: concurrently operating configured QwenPaw agents/jobs whose model starts traverse the same shipped Hub quota scope. - Inter-S1 disturbance: sibling operations can concurrently consume the same constrained upstream model-service quota, producing a structurally evidenced shared-capacity collision and upstream overload/429 pressure. - Attenuating coordination relation: SharedLimiter aggregates the shared quota scope, tracks active/rate state, applies the strictest shared limit and admits, rejects or cools down starts. - Feedback into subsequent S1 behaviour: rejected starts receive retry/cooldown state, and later sibling starts are admitted only after the shared limiter state permits them. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the positive mapping is tied to attenuation of a specific inter-S1 shared-resource interference class; generic sub-agent messaging, routing and delegation are not used as evidence. - Why this is / is not agent-owned: QwenPaw owns a concrete coordination construction tied to a real shared-resource interference class, but the admission decision is deterministic host enforcement rather than an autonomous agent&#39;s coordination judgment. This supports C, not A. - Evidence: src/qwenpaw/hub/modelservice/limiter.py; src/qwenpaw/cli/main.py; pyproject.toml; multi-agent management surfaces establishing plural configured QwenPaw agents. - Basis: explicit + structural. - Confidence: medium-high. - Caveats: generic sub-agent delegation and background queues are not used as S2 evidence. The positive mapping relies specifically on shared quota interference and its first-party attenuation loop.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: keep the current QwenPaw installation&#39;s active agent population, automation and risky tool execution within the operator&#39;s present-time control. - Disturbance / variety regulated: agents that should be enabled/disabled, scheduled/heartbeat work, pending risky actions, backend/model state and current runtime conditions that require operator intervention. - Decisive decision or feedback right: enable or disable configured agents, approve or deny gated actions, alter/stop current automation and choose current installation controls exposed through first-party Console/API/CLI surfaces. - Decision owner: the local self-hosting user/operator as legitimate parent actor. - Supporting / enforcement mechanisms: agent inventory/status/toggle API, Console controls, cron/heartbeat administration, tool-guard approval queue, runtime/session status and deterministic enforcement of returned decisions. - Closure path: QwenPaw exposes current installation/agent/action state → parent operator decides a control intervention or approval → first-party API/runtime applies it → subsequent agent/tool operation proceeds under the changed current-control state. - Boundary reachability: src/qwenpaw/app/routers/agents.py exposes configured agents with enabled/startup/backend/model state and mutation paths; first-party control surfaces apply parent changes to the managed installation. - Why this is / is not agent-owned: QwenPaw supplies the installation-wide visibility and control surface but does not replace the parent with an autonomous whole-system controller. The decisive current-control rights remain with the operator, so the state is P. - Evidence: src/qwenpaw/app/routers/agents.py; runtime/tool approval and cron/heartbeat administration paths. - Basis: explicit + structural. - Confidence: medium-high. - Caveats: isolated settings or an approval prompt alone would not establish S3; the positive claim is the parent control relation spanning the active agent population and current automation/action state. - Whole-system current view: the first-party management plane exposes all configured agents and their enabled/startup/backend/model state alongside automation and approval/runtime controls for the installation. - Current-control decision scope: parent intervention over which agents/automations may run now and whether gated actions may proceed.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: challenge ordinary runtime and configuration-health claims through a complementary read-only diagnostic path that probes actual filesystem, process, provider, channel, workspace, skill, cron, memory and security state. - Disturbance / variety regulated: latent divergence between what ordinary runtime/configuration surfaces imply and what the installation can actually read, reach, load or execute. - Decisive decision or feedback right: produce an audit finding from raw diagnostic probes and expose concrete failure/hint information for corrective current control. - Decision owner: constructor-level first-party diagnostic mechanism; QwenPaw supplies deterministic audit judgments and complementary access, but no autonomous auditor owns discretionary S3 judgment. - Supporting / enforcement mechanisms: qwenpaw doctor, read-only doctorchecks, runtime health/API probes, raw config and workspace checks, provider/model connectivity checks, channel connectivity checks, skill/cron/memory/security diagnostics, and the separately invoked doctor fix repair path. - Closure path: ordinary operation/configuration claims a usable installation → qwenpaw doctor independently probes underlying runtime/filesystem/connectivity state → failures and actionable hints are surfaced → operator/current-control paths can repair, reconfigure or restart → subsequent operation reflects the correction. - Boundary reachability: qwenpaw doctor is a shipped first-party CLI command at the frozen revision; its checks explicitly run read-only against installed QwenPaw state and do not require an external evaluator or development-only actor. - Why this is / is not agent-owned: the complementary diagnostic relation is real and specifically packaged, but the audit judgment is deterministic code and corrective authority remains outside an autonomous auditor. That establishes C, not A; Methodology 0.3.x does not publish a parent modifier for S3. - Evidence: src/qwenpaw/cli/doctorchecks.py; src/qwenpaw/cli/doctorcmd.py; src/qwenpaw/cli/doctorconnectivity.py; separate repair path in src/qwenpaw/cli/doctorfixrunner.py. - Basis: explicit + structural. - Confidence: high. - Caveats: ordinary governance logs, traces and status endpoints are not themselves counted as S3. The positive claim is limited to the deliberately read-only complementary doctor path; an autonomous independent auditor is not supplied. - Claim being audited: that the configured QwenPaw installation and its agents/providers/channels/skills/cron/memory/security/runtime dependencies are actually healthy and usable, rather than merely configured or nominally running. - Ordinary reporting path: normal agent/runtime status, configuration, traces, governance logs and service operation report the primary execution path. - Complementary access path: doctor reads raw configuration/workspace/filesystem state, probes the running HTTP service and Python environment, checks provider/model reachability and inspects channel, skill, cron, memory and security conditions without mutating them. - Independence boundary: the diagnostic CLI/check functions are outside the conversational model decision path and explicitly read-only; they access underlying operating reality directly, although they remain first-party deterministic QwenPaw code rather than a separate autonomous actor. - Who acts on findings: the self-hosting operator/current-control layer uses reported FAIL/hint output and may invoke the separate doctor fix path, reconfigure the installation or restart affected components.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:4\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A - Function: anticipate likely future user needs from recent operating evidence, gather fresh external/local evidence for those needs and return a useful intervention into later QwenPaw operation. - Disturbance / variety regulated: changing recent user interests/work, likely near-future goals, stale knowledge and external/local conditions that could make a proactive intervention useful or irrelevant. - Decisive decision or feedback right: infer and rank likely future tasks/queries from recent memory context, choose which candidate to investigate, determine whether newly gathered evidence is sufficient and decide whether to send a proactive result or remain silent. - Decision owner: the first-party proactive model actor instantiated by QwenPaw&#39;s proactive responder. - Supporting / enforcement mechanisms: recent-memory context builder, optional desktop evidence, task extraction, web/file/shell/browser retrieval tools, activity-abort checks, success/failure self-check and proactive Console delivery. - Closure path: recent user/operating evidence → model derives likely future tasks → QwenPaw gathers fresh evidence/executes a candidate → model/runtime checks usefulness/completion → successful proactive message is posted into QwenPaw Console/chat → subsequent user/agent operation receives the prospective intervention. - Boundary reachability: generateproactiveresponse is first-party QwenPaw code reached by the supported proactive feature/background loop; it creates the proactive assistant, derives tasks and closes successful output through QwenPaw&#39;s own Console chat API. - Why this is / is not agent-owned: enabling proactive mode is parent consent/configuration, but the substantive prospective judgment — what future need is likely, what to investigate and whether to speak — is made by the model actor. ReMe&#39;s separate auto-dream internals are not needed for this positive mapping. - Evidence: src/qwenpaw/agents/memory/proactive/proactiveresponder.py; proactive feature documentation at the reviewed revision. - Basis: explicit + structural. - Confidence: high. - Caveats: ReMe-backed memory context is input evidence only; its internal memory-evolution algorithm is not credited to QwenPaw ownership. - External distinction: the proactive path reads evidence beyond the current inside-and-now control state — recent user behavior plus optional desktop state and fresh web/file/tool evidence. - Future / prospective distinction: the model infers likely next needs and investigates candidate work before a new user request requires that work. - Adaptation option generated: choose and rank a likely future task/query, gather supporting evidence and decide whether a proactive intervention is useful enough to surface or should remain silent. - Path back into current capability / S3: a successful prospective result is injected into first-party QwenPaw Console/chat for subsequent user/agent operation; activity-abort checks suppress stale interventions before delivery.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S5 / identity: - State: P - Function: establish and revise the QwenPaw agent&#39;s durable identity, behavioral principles, boundaries and user relationship that constrain future operation. - Disturbance / variety regulated: ambiguity or drift about who the agent is, how it should behave, its style/tone, user preferences and durable behavioral boundaries. - Decisive decision or feedback right: choose the durable identity/profile/boundary content and whether persona files participate in future system prompts. - Decision owner: the local self-hosting user as legitimate parent actor. - Supporting / enforcement mechanisms: BOOTSTRAP.md, SOUL.md, PROFILE.md, AGENTS.md, Console persona editor, enable/disable/reorder controls and hot-reload/system-prompt loading. - Closure path: identity/boundary issue or initial bootstrap → parent conversation/editor resolves name/nature/style/preferences/boundaries → QwenPaw persists persona files/configuration → those files are loaded into later system prompts → subsequent S1/S4 behavior occurs under the returned identity policy. - Boundary reachability: the persona system is documented as a standard workspace feature; bootstrap explicitly asks the user to resolve identity/preferences/boundaries and writes durable PROFILE.md/SOUL.md, while Console editing/hot reload changes later prompts. - Why this is / is not agent-owned: QwenPaw supplies the identity-construction mechanism and can help elicit the choices, but the ultimate durable identity/boundary authority remains with the user. This is parent-governed S5, not autonomous S5. - Evidence: website/public/docs/persona.en.md; shipped workspace persona files and Console persona editing/loading paths. - Basis: explicit + structural. - Confidence: high. - Caveats: ordinary system prompts or model settings are not counted by themselves; the positive mapping relies on the explicit parent identity/boundary resolution and durable return into future operation. - Identity / ultimate-policy issue: agent name/nature/style, behavioral principles, relationship to the user, preferences and boundaries that should persist across future sessions. - Ultimate authority in each claimed mode: in the claimed parent-governed mode, the self-hosting user can create, edit, enable, disable and reorder the durable persona surfaces and therefore retains ultimate identity authority. - Return-to-operation path: saved persona files are hot-reloaded/loaded into subsequent system prompts and therefore constrain later operation.\">P</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/974394ae2c33f4e0a2aba0e92939ded05a19f30f/assessments/qwenpaw.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 974394ae2c33f4e0a2aba0e92939ded05a19f30f\">974394a &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-09-24T20:25:35+03:00\"><th scope=\"row\"><a href=\"https://github.com/A-EVO-Lab/a-evolve\" target=\"_blank\" rel=\"noopener\">A-Evolve</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-24\">2026-09-24</time></td><td class=\"review-ref\"><a href=\"https://github.com/A-EVO-Lab/a-evolve/tree/18ba996dac9843f2759b2cdf8a94022f58fbfeb9\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 18ba996dac9843f2759b2cdf8a94022f58fbfeb9\">18ba996 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: perform the task/environment work whose outcomes the evolving organization is intended to improve. - Disturbance / variety regulated: task-specific repository/environment state, tool/API/container feedback, implementation or reasoning uncertainty, execution errors, and other local distinctions presented by the selected task distribution. - Decisive decision or feedback right: choose the substantive task actions, tool calls, code/environment changes and stopping/submission behavior needed to solve the current task within the bound operational agent. - Decision owner: the autonomous model-driven actor instantiated by the selected first-party BaseAgent implementation; the bundled SWE reference path constructs a real strands.Agent with the current workspace prompt/tools/skills and invokes it on the task. - Supporting / enforcement mechanisms: BaseAgent workspace loading/export/reload, manifest/entrypoint resolution, tool registry/loading, benchmark task loading, container/environment wrappers, model-provider bindings, trajectory capture, optional deterministic step limits and submission tooling. - Closure path: benchmark/environment supplies a task → A-Evolve invokes BaseAgent.solve() → autonomous agent chooses task actions and receives local tool/environment feedback → a Trajectory/operational result is returned → the result enters evaluation/observation and later organizational adaptation. - Boundary reachability: the documented ae.Evolver(agent=&quot;swe-verified&quot;, benchmark=&quot;swe-verified&quot;)/built-in seed path resolves a shipped first-party workspace manifest to SweAgent; Evolver.run() directly invokes the same BaseAgent through EvolutionLoop. The autonomous S1 actor is therefore reachable in the standard distribution without borrowing an adjacent repository-development agent. - Why this is / is not agent-owned: deterministic workspace/container/tool machinery constrains execution, but it does not choose the substantive task actions. Under the counterfactual owner test, retaining those mechanisms without the model-driven BaseAgent actor removes the operational decision right. - Evidence: agentevolve/api.py; agentevolve/protocol/baseagent.py; seedworkspaces/swe/manifest.yaml; agentevolve/agents/swe/agent.py; agentevolve/engine/loop.py. - Basis: explicit + structural. - Confidence: high. - Caveats: arbitrary adopter-supplied BaseAgent internals are not inherited into A-Evolve. The positive state is grounded in the first-party protocol plus bundled reference-agent operating mode directly reached by the standard Evolver API.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party S2 relation is established at the reviewed evolving-agent recursion. - Disturbance / variety regulated: not established as an inter-S1 disturbance. The standard EvolutionLoop binds one operational BaseAgent; multiple benchmark tasks or parallel task processes are repeated/isolated episodes of that operation rather than evidenced sibling S1 units whose interaction generates a conflict or oscillation requiring mutual coordination. - Decisive decision or feedback right: not established for S2. - Decision owner: not established. - Supporting / enforcement mechanisms: batch sizing, optional solve parallelism, process/container isolation, task sequencing, workspace copying, benchmark splitting and evolution-cycle ordering. - Closure path: not applicable for the negative finding. - Why this is / is not agent-owned: scheduling and isolation may prevent implementation interference, but the reviewed standard distribution does not establish two distinct S1 units plus a specific interaction-generated disturbance and a coordination response that changes their subsequent peer behavior. - Evidence: DESIGN.md; agentevolve/engine/loop.py; agentevolve/config.py. - Basis: explicit + structural negative search. - Confidence: high. - Caveats: A-Evolve can evolve multi-agent implementations and contains specialized research/example machinery, but agent plurality in an input agent or experiment is not transferred into the standard generic A-Evolve boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no distinct whole-system inside-and-now current-control function is established at the reviewed evolving-agent boundary. - Disturbance / variety regulated: A-Evolve tracks task/cycle status, scores, workspace history and convergence, but those surfaces either execute the operational task lifecycle or support prospective adaptation; no separate actor is shown regulating current shared resources, commitments, priorities or constraints on behalf of multiple current operations. - Decisive decision or feedback right: not established for S3. - Decision owner: not established. - Supporting / enforcement mechanisms: deterministic cycle sequencing, batch/task selection, score calculation, Git snapshots, convergence checks, configured limits, trial execution and optional navigation/promotion thresholds. - Closure path: not applicable for the negative finding. - Why this is / is not agent-owned: the evolution-engine agent owns adaptation choices mapped to S4, while the operational agent owns task-local S1 choices. Deterministic loop/gating/versioning machinery applies configured lifecycle rules but does not evidence discretionary whole-system current-control authority. - Evidence: agentevolve/engine/loop.py; agentevolve/config.py; DESIGN.md. - Basis: explicit + structural negative search. - Confidence: high. - Caveats: an evolution engine can decide what future capability should change, but prospective adaptation is not reclassified as S3 merely because it changes the currently persisted workspace.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: provide a complementary evidence path that can challenge the operational agent&#39;s trajectory/result against benchmark-specific ground truth or an independent evaluator and feed the resulting discrepancy information into later regulation/adaptation. - Disturbance / variety regulated: S1 may return an apparently plausible result or trajectory that fails task/environment ground truth, tests, judge criteria or other benchmark-specific outcome checks not available from the operational actor&#39;s own report alone. - Decisive decision or feedback right: determine whether/how the completed operational trajectory satisfies the independent benchmark criterion and return structured Feedback describing the result sufficiently for later diagnosis. - Decision owner: constructor-dependent. A-Evolve specifies and wires the S3-specific BenchmarkAdapter.evaluate(task, trajectory) -&gt; Feedback path and ships concrete adapters, but the decisive audit criterion/judge is supplied by the selected benchmark/evaluator configuration rather than one packaged autonomous audit actor common to the standard distribution. - Supporting / enforcement mechanisms: BenchmarkAdapter contract, built-in adapters, task/environment ground truth, Docker/API/judge integrations, Observation persistence, Observer/History and deterministic transport of feedback into the evolution loop. - Closure path: operational BaseAgent returns a trajectory/result → separate benchmark adapter evaluates it against its own evidence/ground truth → structured feedback is attached to the observation/history → the evolution engine can use the discrepancy evidence when choosing later workspace/capability changes → the changed operational agent executes later cycles. The constructor supplies this complete function-specific path, while the audit owner/criterion depends on the configured adapter. - Boundary reachability: every ordinary non-self-evaluating EvolutionLoop cycle calls the bound benchmark adapter&#39;s evaluate() after agent.solve(), and the documented Evolver API requires/resolves a benchmark. The first-party complementary-evidence path is therefore a normal supported construction surface, not an adjacent CI/test-only mechanism. - Why this is / is not agent-owned: BenchmarkAdapter explicitly separates operational production from the independent judgment path, but A-Evolve does not package a single autonomous audit actor owning that judgment across benchmarks. A deterministic/test-based or externally supplied judge may close a concrete instantiated audit path; the generic first-party distribution therefore exposes a real S3-specific constructor rather than autonomous A ownership. - Claim being audited: that the operational agent&#39;s returned trajectory/result correctly satisfies the current benchmark task/environment criterion. - Ordinary reporting path: BaseAgent.solve(task) returns the agent-generated Trajectory, output/patch and tool/action trace from ordinary S1 execution. - Complementary access path: benchmark-specific evaluate() can use ground truth, tests, containers, API results or separate judge logic outside the S1 actor&#39;s ordinary self-report. - Independence boundary: the benchmark adapter is a separate component from BaseAgent; its dataset/evaluation logic is selected independently of the operational agent and is not defined by the S1 trajectory itself. The exact independence strength remains adapter-specific, which is one reason the generic state is constructor-owned. - Who acts on findings: the configured evolution-engine agent consumes persisted observations/history and can convert the feedback into future workspace adaptations; deterministic loop/versioning machinery then closes those adaptations into subsequent S1 operation. - Evidence: agentevolve/benchmarks/base.py; agentevolve/engine/loop.py; agentevolve/api.py; QUICKSTART.md. - Basis: explicit + structural. - Confidence: medium-high. - Caveats: ordinary S1 self-verification, solver skill proposals and generic logs are not credited as S3. The positive constructor is specifically the separate benchmark/evaluation path. A concrete downstream instantiation may have stronger deterministic or autonomous audit ownership, but that does not upgrade the generic A-Evolve distribution to S3=A.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:4\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A - Function: interpret task/environment evidence across operational episodes into persistent adaptation options and autonomously change present capability so later operation can respond differently. - Disturbance / variety regulated: recurring task failures, trajectory/tool-use patterns, benchmark/environment feedback, newly encountered task distinctions and other evidence that the current prompt/skill/memory/tool repertoire is insufficient for future tasks in the relevant distribution. - Decisive decision or feedback right: choose which persistent workspace adaptations to make from accumulated evidence — including prompt, skill and memory changes by default — and thereby alter the operational repertoire exposed to subsequent S1 runs. - Decision owner: the autonomous LLM actor inside the default first-party AEvolveEngine; it receives the evolution prompt/history context and workspace-scoped bash tools and decides what to inspect and mutate. - Supporting / enforcement mechanisms: Observer/history collection, trajectory files/indexing, benchmark feedback where exposed by the configured mode, EvolveConfig mutation permissions, workspace filesystem contract, Git pre/post snapshots, optional trials/gates/rollback machinery, deterministic cycle sequencing and BaseAgent.reloadfromfs(). - Closure path: S1 executes tasks in an external/task environment → trajectories and available feedback are recorded → the autonomous evolution-engine actor interprets recent evidence and chooses persistent workspace changes → A-Evolve writes/commits the changed prompt/skills/memory/tool state → BaseAgent.reloadfromfs() reloads the changed capability → later tasks/cycles are solved using the evolved repertoire, producing new evidence for another adaptation cycle. - Boundary reachability: Evolver defaults to AEvolveEngine when the caller does not supply another engine; default EvolveConfig enables prompt, skill and memory evolution; bundled seed workspaces expose evolvable layers and hot reload; the documented Quick Start&#39;s ordinary evolution tutorial executes the solve → observe → evolve → reload loop. The autonomous S4 path is therefore a first-party standard mode rather than a research-only adjacent actor. - Why this is / is not agent-owned: deterministic code controls when a cycle starts, what layers are writable and how mutations are versioned/reloaded, but it does not choose the substantive adaptation. Removing the evolver LLM while leaving Observer, Git, config and reload machinery preserves evidence/enforcement but removes the discretionary choice of what future capability should change. - External distinction: task/environment trajectories and, depending on benchmark/configuration, independent evaluation/feedback expose distinctions about where the current operational repertoire succeeds, fails or behaves poorly in the relevant external task distribution. - Future / prospective distinction: the evidence is analyzed after/between operational episodes specifically to improve performance on later tasks/cycles; it is not merely current-episode retry or context continuation. - Adaptation option generated: the evolver may add/replace/refine persistent prompts, skills and memory by default, with tools/infra available under configuration; default AEvolveEngine autonomously selects concrete workspace mutations using recent observation history. - Path back into current capability / S3: selected adaptations are written into the bound AgentWorkspace, committed/versioned, and then reloaded by BaseAgent.reloadfromfs() before later S1 operation. No separate positive S3 mapping is required for this implementation topology; the S4 return path reaches operational capability directly through the shared workspace contract. - Evidence: README.md; QUICKSTART.md; DESIGN.md; agentevolve/api.py; agentevolve/config.py; agentevolve/engine/loop.py; agentevolve/algorithms/skillforge/engine.py; seedworkspaces/swe/manifest.yaml; agentevolve/protocol/baseagent.py. - Basis: explicit + structural. - Confidence: high. - Caveats: published benchmark gains and research-paper scores are capability evidence and are not used to establish S4 ownership. Bring-your-own agents/engines remain separate constructor configurations; the A claim rests on the shipped default autonomous evolution engine plus bundled first-party operational workspaces and documented integrated loop. Human selection of initial config or manual workspace edits does not establish a distinct operationally closed S4 parent mode.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no runtime identity/ultimate-policy closure is established at the reviewed evolving-agent boundary. - Disturbance / variety regulated: manifests, evolution configuration, allowed writable layers, model choices and benchmark selection constrain the run, but the reviewed standard distribution does not surface an identity/ultimate-policy conflict to a legitimate authority that decides it and returns a governing decision into subsequent operation. - Decisive decision or feedback right: not established for S5. - Decision owner: not established. - Supporting / enforcement mechanisms: manifest.yaml, EvolveConfig, writable-layer flags, system prompts, benchmark choice, model/provider configuration, workspace contract and operator launch arguments. - Closure path: not applicable for the negative finding. - Why this is / is not agent-owned: the evolver has broad discretion to adapt permitted operational capability, but it acts inside developer/operator-selected identity and mutation boundaries. Capability self-improvement is S4 here; it does not establish authority to redefine the organization&#39;s ultimate purpose or policy. - Evidence: agentevolve/config.py; seedworkspaces/swe/manifest.yaml; agentevolve/api.py; DESIGN.md. - Basis: explicit + structural negative search. - Confidence: high. - Caveats: maintainers/operators can configure or modify the software, but generic configuration/development authority is not runtime S5 at this recursion.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/2fcbd43788bc436aa146b06d89f80df7dddc2cf4/assessments/a-evolve.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 2fcbd43788bc436aa146b06d89f80df7dddc2cf4\">2fcbd43 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-09-21T20:03:50+03:00\"><th scope=\"row\"><a href=\"https://github.com/inngest/utah\" target=\"_blank\" rel=\"noopener\">Utah</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-21\">2026-09-21</time></td><td class=\"review-ref\"><a href=\"https://github.com/inngest/utah/tree/b3aeb81c076f2a03d78fc291417c55439f796d61\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision b3aeb81c076f2a03d78fc291417c55439f796d61\">b3aeb81 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: perform user- or event-directed work through a model-driven think/action/tool-observation loop. - Disturbance / variety regulated: ambiguous requests, external web/filesystem/tool state, tool failures, model responses, changing conversation context and returned subordinate results. - Decisive decision or feedback right: choose substantive next tool/action steps from current context and observations and decide when to return an operational result. - Decision owner: the running Utah model agent. - Supporting / enforcement mechanisms: createAgentLoop, first-party tool dispatch, Inngest durable steps/retries, session/context persistence, compaction/pruning, model-provider adapter and channel/event transport. - Closure path: user/event work → model decision → selected tool/sub-agent action → first-party execution → observation returned to the model → revised action or final response → persisted/emitted result. - Boundary reachability: the repository-shipped worker enters agent-handle-message, which directly invokes the first-party Utah loop; no downstream harness implementation is required. - Why this is / is not agent-owned: Inngest and Utah runtime code provide durable execution and enforce bounds, while the model actor owns the discretionary choice of substantive next action from current evidence. - Evidence: README.md, src/agent-loop.ts, src/lib/tools.ts, src/functions/message.ts. - Basis: explicit + structural. - Confidence: high. - Caveats: pi-ai, pi-coding-agent and model providers supply execution/tool substrate but are not imported as organizational owners.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party path establishes regulation of a concrete interference, conflict or oscillation among at least two distinct S1 units. - Disturbance / variety regulated: not established as S2 at the reviewed recursion. - Decisive decision or feedback right: not established for S2. - Decision owner: not established for S2. - Supporting / enforcement mechanisms: per-session singleton cancellation, synchronous/async/scheduled delegation, event routing and shared workspace state exist, but none is credited without the Profile-required inter-S1 disturbance relation. - Closure path: not applicable. - Why this is / is not agent-owned: singleton: { key: sessionKey, mode: &quot;cancel&quot; } prevents overlapping runs of the same conversation, but duplicate/current runs of one conversational unit are not evidence of two distinct S1 units. Delegation and event transport likewise do not establish S2 by themselves. - Evidence: src/functions/message.ts, src/agent-loop.ts, src/lib/tools.ts. - Basis: structural absence review. - Confidence: high. - Caveats: a downstream organization of multiple Utah agents could add an S2 relation, but that relation is not supplied by the reviewed standard distribution.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no material first-party path establishes whole-system current regulation over a portfolio of operational units or commitments. - Disturbance / variety regulated: not established as S3 at the reviewed recursion. - Decisive decision or feedback right: not established for whole-current-system control. - Decision owner: not established for S3. - Supporting / enforcement mechanisms: the main agent can start sync/async/scheduled sub-agent work; Inngest enforces retries/singleton/cancellation; failure and heartbeat functions maintain execution continuity. - Closure path: not applicable as S3. - Why this is / is not agent-owned: creating a subordinate task is delegation, not whole-system regulation. The reviewed Utah tool surface does not give the model a first-party current portfolio view plus discretionary list/inspect/reprioritize/cancel/reallocate authority across ongoing subordinate commitments. - Evidence: src/agent-loop.ts, src/lib/tools.ts, src/functions/message.ts. - Basis: structural absence review. - Confidence: medium-high. - Caveats: Inngest may expose infrastructure-level run management outside Utah, but external platform controls are not inherited as Utah-owned S3.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material first-party path establishes sufficiently independent complementary access to operational reality plus corrective return into S1/S3. - Disturbance / variety regulated: not established as S3 at the reviewed boundary. - Decisive decision or feedback right: not established. - Decision owner: not established. - Supporting / enforcement mechanisms: durable step observability, retries, failure notification, session logs, memory distillation and optional user-authored review functions provide execution evidence or future extensibility rather than a shipped independent auditor. - Closure path: not applicable. - Why this is / is not agent-owned: ordinary tool results are already the production feedback path; Inngest observability/retry is execution infrastructure; memory summarization changes retained context; a hypothetical generated review loop is not a standard-distribution audit owner until such a loop actually exists and closes the S3 function. - Evidence: README.md, src/agent-loop.ts, src/sidecar/sidecar.ts. - Basis: structural absence review. - Confidence: medium-high. - Caveats: the sidecar makes independent review workflows constructible, but constructor/extensibility potential is not a positive S3 mapping without the function-specific closing path.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:4\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A - Function: turn learned or anticipated reusable environmental/workflow distinctions into persistent future capabilities that change later Utah operation. - Disturbance / variety regulated: recurring external events, monitoring needs, repeated workflows, newly learned API/codebase/process patterns, user-taught reusable practices and techniques that should survive the current conversation. - Decisive decision or feedback right: decide that a learned/current distinction warrants durable future adaptation and choose what reusable skill or event/scheduled function to create or update. - Decision owner: the running Utah model agent, using its normal first-party workspace tools under the bundled adaptation guidance. - Supporting / enforcement mechanisms: first-party write/edit/bash tool access to the workspace, creating-skills.md, inngest-functions.md, prompt-time skill indexing/loading, the sidecar file watcher/dynamic import/reconnect path and Inngest&#39;s durable event/cron execution substrate. - Closure path: operational/user/environmental experience → model recognizes a reusable or prospective need → agent writes/updates a workspace skill and/or workspace/functions/.ts function → later conversations load the changed skill and/or utah-sidecar hot-loads the function → future cron/event executes the new capability → resulting action or agent.message.received event changes later operation. - Boundary reachability: the standard main agent already has the file tools required to mutate its workspace, bundled Utah skills explicitly teach the agent when/how to create persistent skills and dynamic functions, and the shipped sidecar watches/loads those functions without downstream deployment code or human approval. - Why this is / is not agent-owned: Inngest supplies durable scheduling/execution and the sidecar mechanically loads valid files, but the model agent owns the discretionary adaptation decision and authors the new future-facing repertoire. Removing that agent leaves the loader but not the choice of what learned capability to create. - Evidence: README.md, src/lib/tools.ts, src/lib/context.ts, skills/creating-skills.md, skills/inngest-functions.md, src/sidecar/sidecar.ts. - Basis: explicit + structural. - Confidence: high. - Caveats: memory distillation, self-editing and file writing are not credited alone. The positive mapping rests on the prospective adaptation loop that introduces durable reusable skills/functions into future execution. - External distinction: recurring environmental events, reusable workflow patterns, newly learned techniques and user-taught practices that matter beyond the present conversation. - Future / prospective distinction: the selected adaptation is encoded for later conversations, scheduled times or future events rather than only repairing the current turn. - Adaptation option generated: create or revise a persistent workspace skill and/or author a new durable Inngest cron/event/multi-step function. - Path back into current capability / S3: later prompt construction loads changed skills; the sidecar hot-loads changed functions, whose future execution can act directly or emit agent.message.received back into Utah&#39;s operational loop.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no material first-party path establishes identity- or ultimate-policy-level adjudication that closes unresolved present/future tension for the Utah organization. - Disturbance / variety regulated: not established as S5 at the reviewed recursion. - Decisive decision or feedback right: not established for identity/ultimate policy. - Decision owner: not established for S5. - Supporting / enforcement mechanisms: IDENTITY.md, SOUL.md, USER.md, environment configuration and ordinary user instructions shape behavior; the agent&#39;s file tools can modify workspace files. - Closure path: not applicable as S5. - Why this is / is not agent-owned: editable identity/persona text is configuration and context. The reviewed runtime does not establish a legitimate identity-level issue/proposal → ultimate authority → returned policy decision path, nor an autonomous actor authorized to settle S3–S4 tension at that level. - Evidence: README.md, src/lib/context.ts, src/lib/tools.ts. - Basis: structural absence review. - Confidence: high. - Caveats: a parent user can edit identity/policy files, but generic configuration authority is not S5 without a qualifying identity/ultimate-policy decision and closure path.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/fc5cfe03522cb573d2ac17d6527c93261caed30e/assessments/utah.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit fc5cfe03522cb573d2ac17d6527c93261caed30e\">fc5cfe0 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-09-21T15:34:42+03:00\"><th scope=\"row\"><a href=\"https://github.com/nearai/ironclaw\" target=\"_blank\" rel=\"noopener\">IronClaw</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-21\">2026-09-21</time></td><td class=\"review-ref\"><a href=\"https://github.com/nearai/ironclaw/tree/b0b999d96781516ee05e6ba961d6f3ead900da96\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision b0b999d96781516ee05e6ba961d6f3ead900da96\">b0b999d &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: execute user-directed or background work through a model-driven plan/tool/observation loop and produce operational outcomes. - Disturbance / variety regulated: ambiguous requests, tool/service observations, model results, persistent context, capability availability and execution failures. - Decisive decision or feedback right: choose substantive next actions/tools and revise the plan from returned observations within configured authority. - Decision owner: the running IronClaw model agent/job. - Supporting / enforcement mechanisms: canonical executor/planner, durable turn state, capability resolver, authorization/approval gates, tool runtimes, checkpoints and model transport. - Closure path: request/job state → model decision → authorized capability/tool action → returned observation/checkpoint → subsequent model decision → result. - Boundary reachability: the shipped ironclaw composition invokes the first-party canonical agent-loop executor; no downstream harness must be supplied to create the operational model/tool loop. - Why this is / is not agent-owned: runtime code transports and constrains actions, while the model loop owns the substantive choice of action and follow-up from current evidence. - Evidence: AGENTS.md, crates/loop/ironclawagentloop/README.md, README.md. - Basis: explicit + structural. - Confidence: high. - Caveats: provider inference is external execution substrate, not an imported organizational owner.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: attenuate shared provider/system-capacity contention among distinct concurrently runnable job S1 units. - Disturbance / variety regulated: too many jobs simultaneously consuming finite LLM-provider concurrency and local runtime resources. - Decisive decision or feedback right: admit a Pending job to execution only when a concurrency slot is available. - Decision owner: first-party deterministic scheduler/concurrency policy; no autonomous S2 actor is established. - Supporting / enforcement mechanisms: isolated job contexts, MAXPARALLELJOBS, Pending queue and creation-order dispatch. - Closure path: concurrent runnable jobs exceed the configured shared-capacity envelope → excess work remains Pending → completion/cancellation frees a slot → scheduler admits queued work → subsequent S1 execution proceeds inside the bounded envelope. - Boundary reachability: parallel jobs and the bounded scheduler are standard first-party job behavior documented for the shipped instance; no downstream coordinator is required. - Why this is / is not agent-owned: the S2-specific attenuation relation is first-party and operational, but the coordination decision is deterministic policy rather than a model agent choosing how to reconcile the competing units. - Evidence: docs/capabilities/jobs/jobs.mdx, docs/capabilities/routines/cron.mdx, .env.example. - Basis: explicit + structural. - Confidence: medium-high. - Caveats: generic job sequencing is not the basis; the credited witness is bounded shared-capacity contention across concurrently runnable S1 jobs. - Distinct S1 units: independently executing IronClaw jobs with isolated contexts. - Inter-S1 disturbance: simultaneous jobs contend for shared LLM-provider concurrency and available instance resources. - Attenuating coordination relation: a first-party maximum-concurrency envelope and Pending queue prevent all runnable jobs from consuming the shared resource at once. - Feedback into subsequent S1 behaviour: queued units remain Pending and become InProgress only after another unit releases capacity. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the queue/cap is explicitly tied to the finite shared capacity that concurrent S1 execution would otherwise overrun; it regulates a concrete cross-unit interference rather than merely choosing message order.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: regulate the current portfolio of active/pending background work for the IronClaw instance. - Disturbance / variety regulated: new work demand, current job state, stalled or no-longer-needed jobs and changing current priorities. - Decisive decision or feedback right: create new work, inspect the full active-job portfolio/status and cancel current Pending/InProgress commitments. - Decision owner: the model-driven IronClaw agent using the standard job-control tools. - Supporting / enforcement mechanisms: job repository/state machine, scheduler, createjob, listjobs, jobstatus, canceljob and self-repair state transitions. - Closure path: current job portfolio/state → agent listjobs/jobstatus observation → model current-control decision → create/cancel/continue action → scheduler/job state changes → new portfolio state available to the agent. - Boundary reachability: all four job-control capabilities are documented as built-in tools in the shipped job subsystem and are available to the standard agent path. - Why this is / is not agent-owned: scheduler and self-repair enforce mechanics, but the discretionary decision to add or cancel current commitments from the current portfolio is made by the model agent. - Evidence: docs/capabilities/jobs/jobs.mdx, docs/capabilities/jobs/self-repair.mdx. - Basis: explicit. - Confidence: high. - Caveats: timeout/retry and concurrency enforcement are not treated as autonomous S3 ownership. - Whole-system current view: listjobs exposes all active jobs with current state/metadata, with jobstatus providing per-job detail. - Current-control decision scope: create a new commitment or cancel an existing Pending/InProgress job, thereby changing the current work portfolio.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material first-party runtime path establishes an independent complementary audit owner whose distinct operational-reality findings close back into corrective S1 behavior. - Disturbance / variety regulated: not established as S3 at the reviewed runtime boundary. - Decisive decision or feedback right: not established. - Decision owner: not established. - Supporting / enforcement mechanisms: deterministic authorization/safety gates, logs/audit sinks, self-repair monitoring and repository-development audits exist but do not establish runtime S3 ownership. - Closure path: not applicable. - Why this is / is not agent-owned: self-repair observes inactivity mechanically and security controls enforce policy; development audits/reviewer agents operate outside the credited product runtime. - Evidence: docs/capabilities/jobs/self-repair.mdx, docs/internal/reborn/target-architecture/ws12-security-audit.md. - Basis: negative after targeted runtime/development-surface review. - Confidence: medium-high. - Caveats: audit logging and policy checks may be valuable controls without constituting S3.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S4 / adaptation: - State: P - Function: recognize recurring/future user needs, formulate a persistent automation adaptation and return the parent-approved option into future IronClaw operation. - Disturbance / variety regulated: repeated user work, recurring omissions/forgetting, periodic monitoring needs and learned patterns likely to recur. - Decisive decision or feedback right: approve whether the proposed persistent routine becomes part of future operation. - Decision owner: the user as legitimate parent in the shipped routine-advisor mode. - Supporting / enforcement mechanisms: user/context memory, routine-advisor activation/pattern rules, builtintriggerlist, builtintriggercreate, cron/once schedules and routine execution history. - Closure path: observed recurring pattern/future need → agent proposes specific future automation → user confirms or rejects → on confirmation agent creates the routine → later scheduled/event-driven runs alter future operation. - Boundary reachability: routine-advisor is a shipped first-party skill and explicitly instructs the standard agent to use built-in trigger capabilities after confirmation; no downstream adaptation workflow is required. - Why this is / is not agent-owned: the agent owns pattern detection and option generation, but the skill explicitly says to always wait for user confirmation. The decisive adaptation judgment therefore remains parent-owned. - Evidence: skills/routine-advisor/SKILL.md, docs/capabilities/routines/cron.mdx. - Basis: explicit + structural. - Confidence: high. - Caveats: dynamic tool discovery/building and current-task extension use are not independently credited as S4 without the prospective distinction; the positive claim rests on the explicit recurring-pattern→future-routine path. - External distinction: recurring user behavior, installed-capability context and expressed/learned needs are evidence outside the current internal execution state. - Future / prospective distinction: the advisor distinguishes tasks likely to recur and proposes a schedule for later executions rather than merely solving the present turn. - Adaptation option generated: a concrete persistent routine specifying what future runs do, when they run and how results are delivered. - Path back into current capability / S3: parent confirmation authorizes builtintriggercreate; the installed routine becomes part of the active operational program and later fires as standard jobs. - Parent ownership of decisive adaptation judgment/feedback right: the shipped skill says to wait for the user to confirm before creating any routine. - Return of parent decision into present capability: confirmation permits the agent to install the trigger immediately. - Subsequent operational/capability change under that returned decision: future cron/event fires execute the newly installed recurring program.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no material runtime path establishes an agent or parent closure over IronClaw&#39;s identity or ultimate organizational policy at the declared system boundary. - Disturbance / variety regulated: not established as S5. - Decisive decision or feedback right: not established. - Decision owner: not established. - Supporting / enforcement mechanisms: user requests, settings, authorization/approval policy, agent name/profile, skills and extension permissions constrain operation but do not by themselves constitute S5 closure. - Closure path: not applicable. - Why this is / is not agent-owned: the reviewed surfaces expose operational authority/configuration and action approvals, not a reconstructable identity/ultimate-policy issue resolved by a legitimate S5 owner and returned as governing identity/policy. - Evidence: README.md, docs/extensions/building-a-tool.md, .env.example. - Basis: negative after targeted policy/configuration review. - Confidence: medium-high. - Caveats: human approval of risky tool actions is operational governance; it is not automatically S5=P.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/eebe516174b712a144b143da7afd7b636f6e070b/assessments/ironclaw.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit eebe516174b712a144b143da7afd7b636f6e070b\">eebe516 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-09-22T21:21:46+03:00\"><th scope=\"row\"><a href=\"https://github.com/preloop/preloop\" target=\"_blank\" rel=\"noopener\">Preloop</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-22\">2026-09-22</time></td><td class=\"review-ref\"><a href=\"https://github.com/preloop/preloop/tree/06d53f902d9a8712ea3345ae0bee9b0b8292f917\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 06d53f902d9a8712ea3345ae0bee9b0b8292f917\">06d53f9 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: perform bounded coding, review, security, evidence-collection and other agent work against an admitted objective through a governed external runtime. - Disturbance / variety regulated: heterogeneous tracker events and user objectives, repository/environment state, tool/model feedback, failures, review/CI feedback and task-local uncertainty. - Decisive decision or feedback right: choose the substantive reasoning path, tool calls and task actions within the objective and Preloop policy/budget envelope. - Decision owner: the autonomous external model/agent actor launched or governed by Preloop. - Supporting / enforcement mechanisms: MCP firewall, model gateway, managed credentials, flow execution/runner lifecycle, tool allowlists, budgets, approvals, workspace/checkpoint recovery, runtime plugins and session observability. - Closure path: objective/event is admitted → Preloop starts or governs an agent runtime → the model chooses actions/tools → Preloop mediates calls and returns environment results → the model continues until a bounded result/commit/review/evidence outcome is produced. - Boundary reachability: the frozen README documents onboarding existing agents and launching event/CI-triggered flows through the self-hosted service; supported runtime adapters and private runners reach those external actors directly without relying on repository-development CI. - Why this is / is not agent-owned: Preloop decides admission and enforces constraints, but substantive task-local reasoning and action selection belong to the external model actor. - Evidence: README.md; docs/guide/flows/automated-issue-implementation.md; docs/guide/flows/flow-delegation.md. - Basis: explicit + structural. - Confidence: high. - Caveats: no internal VSM function of Claude Code, Codex, Cursor or another governed runtime is inherited merely because Preloop launches or mediates it.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no installation-level S2 mutual-adjustment function is established from the reviewed standard distribution. - Disturbance / variety regulated: Preloop can run many sessions/flows and maintains lineage, concurrency, budgets and notes, but the inspected paths do not establish a distinct installation-level oscillation/interference among sibling S1 units together with a first-party relation whose organizational purpose is to attenuate that interaction. - Decisive decision or feedback right: not established at the installation recursion. - Decision owner: not established. - Supporting / enforcement mechanisms: child-flow lineage, fan-out/depth/tree budgets, runner concurrency, transactional admission locking, sendnote, waiting/resume and stop propagation structure work and resource use but are not credited as S2 without the required disturbance witness. - Closure path: not applicable for the negative finding. - Why this is / is not agent-owned: no installation-level S2 function was established, so there is no S2 decision right to classify. - Evidence: docs/guide/flows/flow-delegation.md; docs/guide/operator-notes.md; README.md. - Basis: explicit + structural negative search. - Confidence: medium-high. - Caveats: delegation and communication can be ingredients in a downstream S2 design, but generic routing, shared budgets, sequencing and notes do not manufacture the function on their own.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3 / regulation: - State: C(P) - Function: regulate current account-wide agent activity, access and resource commitments using live agent/session/flow/spend/policy state and intervention controls. - Disturbance / variety regulated: active sessions and executions can consume excessive budget, take a wrong operational direction, continue under unsafe tool/model access, or require an immediate account-wide or targeted stop/steer decision. - Decisive decision or feedback right: choose current intervention — change policy/budget/access, steer a live agent, stop an execution, or halt/recover gateway/tool/flow scopes — in response to current installation conditions. - Decision owner: base constructor mode — no resident autonomous installation supervisor is supplied; a downstream controller can be composed over the first-party API/CLI/state/intervention surfaces. Parent mode — the authorized installation/account operator, approver or administrator. - Supporting / enforcement mechanisms: runtime-session timelines, managed-agent/flow inventory, spend attribution, policy engine, approval service, operator-note delivery, execution stop intents, account kill-switch transactions, gateway/tool enforcement and worker recovery/confirmation. - Closure path: current account/session/flow/spend/policy state is observed → controller/operator selects a targeted steer/policy/budget/stop or account halt/recovery action → first-party API/CLI writes that decision → gateway/firewall/scheduler/worker paths enforce it → subsequent current operation is steered, admitted, denied, stopped or resumed under the returned decision. - Boundary reachability: the self-hosted distribution exposes account/session/flow state plus operator-note, policy, approval, budget and kill-switch actions through its console, CLI and HTTP APIs. These are runtime surfaces, not repository-maintainer controls. - Why this is / is not agent-owned: deterministic policies, budgets and kill-switch propagation enforce current decisions but do not decide when policy should change or an emergency intervention should occur. The standard product deliberately exposes the S3-specific observation/intervention path without assigning that installation-wide discretion to a resident autonomous agent. - Evidence: README.md; docs/guide/operator-notes.md; docs/guide/account-kill-switch.md; docs/guide/flows/flow-delegation.md. - Basis: explicit + structural. - Confidence: high. - Caveats: lower-recursion parent agents can autonomously delegate, inspect descendants and send bounded notes, but that does not promote their local management to installation-wide S3 ownership. - Whole-system current view: the control plane maintains account-scoped managed-agent/session/flow state, live timelines and spend/policy information, while the kill-switch status exposes the current account-wide gateway/tools/flows halt state. The function boundary is the governed account rather than every external system an agent may reach. - Current-control decision scope: current policy/budget/access changes, live steering notes, execution stop control and account-wide gateway/tools/flows halt/recovery.\">C(P)</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: independently challenge an implementation/PR claim against fresh code, issue and review evidence and return trusted findings into corrective implementation work. - Disturbance / variety regulated: an implementer may claim completion while the produced change contains defects, security/quality regressions, unmet requirements or current-head CI/review failures. - Decisive decision or feedback right: independently judge the produced PR/change, issue review findings or a review action, and thereby supply corrective feedback that can trigger the next bounded repair execution. - Decision owner: the separate autonomous model actor executing the Pull Request Reviewer flow. - Supporting / enforcement mechanisms: distinct reviewer flow/conversation, bounded PR diff and referenced-issue reads, stateful findings, trusted reviewer actor IDs, provider/current-head gates, runner-controlled verification evidence, feedback debounce/coalescing, branch binding, checkpoints and fresh repair execution budgets/credentials. - Closure path: implementer publishes or updates a PR → separate reviewer flow reads PR/diff/issue evidence and posts findings/review action → durable feedback authenticates configured reviewer identity and current PR/head → feedback is reserved into a fresh implementation repair execution → implementer resumes the bound branch/conversation and addresses findings → later current-head review/CI state is reconciled again. - Boundary reachability: both Pull Request Reviewer and Automated Issue Implementation/durable-feedback modes are shipped first-party presets and runtime services; the reviewer/repair connection is available through normal flow configuration rather than repository-development CI for Preloop itself. - Why this is / is not agent-owned: the critical review judgment is produced by a separate model-driven reviewer conversation, not by the implementation agent or a deterministic gate. Provider and runner checks constrain trusted evidence but do not replace reviewer judgment. - Evidence: docs/guide/flows/pull-request-review.md; backend/presets/002-pull-request-reviewer.yaml; docs/guide/flows/durable-implementation-feedback.md; docs/guide/flows/automated-issue-implementation.md. - Basis: explicit + structural. - Confidence: high. - Caveats: human approval by itself is not credited as S3. The positive claim depends on the distinct autonomous reviewer plus authenticated corrective return; deterministic trusted verification is supporting complementary evidence rather than the sole owner. - Claim being audited: the implementation agent&#39;s produced PR/change and its implicit or explicit claim that the requested change is correct and ready under the relevant review criteria. - Ordinary reporting path: the implementer writes its result/commit and Preloop publishes/binds the PR and implementation execution state. - Complementary access path: the reviewer independently fetches the current PR metadata/diff/comments and referenced issue and may inspect bounded project context; runner/provider gates independently read current-head checks and review state. - Independence boundary: reviewer and implementer are separate flows/conversations; durable feedback distinguishes trustedreviewerids from implementeractorids, ignores untrusted/copied review markers, and creates each repair as a new execution with fresh credentials/budgets. - Who acts on findings: the implementation thread receives trusted review/CI feedback in the next repair execution and the autonomous implementer acts on it; unresolved blockers can instead remain visible for human action.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S4 / adaptation: - State: P - Function: sense external model-provider tariff changes, generate a verified future pricing-policy adaptation and return an approved reviewed feed into serving Preloop processes. - Disturbance / variety regulated: provider models, regional tariffs, cache policies, effective dates and pricing evidence change outside the installation, making existing cost estimates stale or incomplete. - Decisive decision or feedback right: decide whether the externally evidenced candidate pricing revision becomes an approved publication consumed by the installation. - Decision owner: the human/operator who reviews and merges/publishes the pricing change; the scheduled review agent prepares and tests the option but does not own final adoption. - Supporting / enforcement mechanisms: public weekly model-price-review preset, provider/public evidence reads, reviewed catalog and manifest, isolated verification/publication tooling, revision/provenance/expiry validation, allowlists, periodic reviewed-feed polling and atomic runtime price-map replacement. - Closure path: scheduled review examines external provider pricing evidence → agent prepares catalog/manifest/feed changes and tested PR → human reviews and merges/publishes the revision → configured serving processes poll the reviewed artifact → validated price policy replaces current estimates without application deployment → future model-cost control uses the adapted prices. - Boundary reachability: the weekly review preset and reviewed-feed consumer are documented first-party distribution surfaces at the frozen revision. The mode requires normal operator configuration and a human publication decision, not Preloop repository maintainer machinery as an implicit hidden owner. - Why this is / is not agent-owned: the autonomous review agent performs sensing and option generation, but the documented contract explicitly says human PR merge controls feed publication. The decisive adaptation right therefore remains parent-governed. - Evidence: docs/guide/model-price-refresh.md; README.md. - Basis: explicit + structural. - Confidence: high. - Caveats: generic saved-session history, search and replay are not S4. The positive mapping relies specifically on external tariff sensing plus a documented adaptation option and return into runtime pricing. - External distinction: official/public model-provider pricing evidence and regional/cache tariff information are outside Preloop and can change independently of the installation. - Future / prospective distinction: the weekly scheduled review prepares new or future-effective pricing revisions before subsequent governed requests are costed, including explicitly future-dated tariff policies where supported. - Adaptation option generated: the review flow prepares catalog/manifest/generated-feed changes in a tested PR with provenance, effective dates and unresolved-evidence reporting. - Path back into current capability / S3: after parent approval/publication, the reviewed-feed service polls the artifact and atomically replaces serving-process price maps; subsequent current budget/cost regulation uses the updated estimates.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no material first-party identity/ultimate-policy closure is established for the installed Preloop organization. - Disturbance / variety regulated: policy-as-code, roles, approvals, budgets, kill switches, flow configuration and security controls regulate what current/adaptive work may do, but the inspected distribution does not identify an identity/ultimate-policy issue resolved by an ultimate authority and returned as a governing organizational decision. - Decisive decision or feedback right: not established as S5. - Decision owner: not established. - Supporting / enforcement mechanisms: account roles, YAML/CEL tool policy, approvals, model/tool allowlists, budget configuration, kill switch, flow configuration and human merge gates are operational governance mechanisms rather than demonstrated S5 closure. - Closure path: not applicable for the negative finding. - Why this is / is not agent-owned: no S5 function was established to classify; the presence of parent authority over operational controls does not by itself create identity/ultimate-policy governance. - Evidence: README.md; docs/guide/account-kill-switch.md; docs/guide/flows/durable-implementation-feedback.md. - Basis: explicit + structural negative search. - Confidence: high. - Caveats: human-controlled policy and emergency authority are materially important governance, but S5 requires a distinct identity/ultimate-policy function rather than generic high-privilege administration.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/adb765db8190634e8deec410a583bab6cfa955ee/assessments/preloop.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit adb765db8190634e8deec410a583bab6cfa955ee\">adb765d &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-09-25T23:28:32+03:00\"><th scope=\"row\"><a href=\"https://github.com/limecloud/lime\" target=\"_blank\" rel=\"noopener\">Lime</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-25\">2026-09-25</time></td><td class=\"review-ref\"><a href=\"https://github.com/limecloud/lime/tree/3823e9092d4106c877ae08a1d19d593b647cf27d\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 3823e9092d4106c877ae08a1d19d593b647cf27d\">3823e90 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: transform an objective into tool-mediated environmental outcomes through repeated model reasoning/sampling, tool action and observation feedback. - Disturbance / variety regulated: changing task requirements, workspace/file/process state, tool results and failures, provider output, permissions, user steering and durable mailbox input. - Decisive decision or feedback right: choose the next substantive action/tool and revise subsequent work from returned tool/environment evidence. - Decision owner: the active Lime model agent in each root or child session. - Supporting / enforcement mechanisms: provider adapter, current provider turn loop, tool runtime, Thread/Turn/Item projection, session loop, permissions/approvals and persistence/recovery. - Closure path: objective/context → provider/model chooses tool or output → tool runtime applies action → normalized result is appended to the same transcript → subsequent sampling observes the result and chooses the next action → task/environment state changes. - Boundary reachability: standard first-party runtime path used by ordinary root and spawned child sessions. - Why this is / is not agent-owned: deterministic tooling executes and bounds actions, but removing the model removes the substantive next-action judgment while leaving only enforcement machinery. - Evidence: providerturn.rs; README.md. - Basis: explicit + structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: attenuate contention among distinct child S1 operations for bounded concurrent execution capacity within one durable root-agent tree. - Disturbance / variety regulated: multiple child S1s can concurrently demand execution beyond the root-tree child capacity, creating resource contention and unbounded parallel admission. - Decisive decision or feedback right: admit or reject a child turn against root-scoped capacity and release/reuse that capacity as children terminate. - Decision owner: no autonomous S2 actor owns discretionary coordination; the standard path deterministically enforces the configured root-scoped limit. - Supporting / enforcement mechanisms: AgentExecutionLimiter reservations/claims/guards, child residency handling, durable root/thread identity and AgentControl error return. - Closure path: distinct child sessions request execution → limiter observes shared root-scoped active/pending occupancy → atomic reservation admits up to the bound or returns AgentLimitReached → the failed/successful result returns through the AgentControl tool/runtime → the root/child execution pattern changes; completed work releases capacity for later S1 execution. - Boundary reachability: the S2-specific admission/limiting relation is directly on the shipped AgentControl child-execution path: model-visible spawn/follow-up requests reserve or claim root-scoped child slots in App Server before child turns run, and admission failure returns through the ordinary tool/error path; no downstream composition is required to make the contention regulator operative. - Distinct S1 units: each spawned child receives its own durable thread/session and is woken through the normal agent session runtime, so it is a complete operational loop rather than a one-shot model call. - Inter-S1 disturbance: child sessions belonging to the same root compete for the finite child execution slots. - Attenuating coordination relation: first-party root-scoped atomic reserve/claim/release prevents excess simultaneous child execution. - Feedback into subsequent S1 behaviour: admission failure is returned as AgentLimitReached; terminal/released slots permit later child/follow-up work. Root model behavior can therefore change after the coordination result. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the credited relation specifically regulates an evidenced interaction disturbance between multiple S1 operations — contention for the same bounded execution capacity — rather than merely carrying messages or ordering arbitrary work. - Why this is / is not agent-owned: the function-specific path is first-party and complete enough to establish S2, but the decisive capacity rule is deterministic/configured. A developer would need to compose an autonomous coordinator/authority to own that discretion, so publication state is C. - Evidence: agentexecution.rs; agentcontrolgateway.rs. - Basis: explicit + structural -\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: supervise the current root-agent organization by observing the active durable agent tree and changing current task allocation, child commitments and interventions. - Disturbance / variety regulated: changing child progress/state, completed/failed work, queued mailbox activity, need for additional parallel capacity, misdirected/obsolete child work and current decomposition of the root objective. - Decisive decision or feedback right: decide when/what child to spawn, which existing child receives follow-up/current steering, when to wait for results, and when to interrupt a child. - Decision owner: the root model agent through model-visible AgentControl tools. - Supporting / enforcement mechanisms: durable graph/identity store, mailboxes, child session lifecycle, result/state projections, execution limiter, recovery and tool gateway. - Closure path: root agent lists/observes the open tree and/or receives child result/mailbox state → model judges current decomposition/progress → calls spawn/message/follow-up/wait/interrupt → runtime applies the decision to child sessions → child commitments/current operation change → status/result feedback becomes available to the root again. - Boundary reachability: standard model-visible tools are injected into the ordinary first-party runtime and are backed by the App Server&#39;s durable graph/session implementation. - Whole-system current view: listagents enumerates the current open durable root tree and returns each agent&#39;s status and last task message; waitagent returns current child activity/results and state facts. - Current-control decision scope: root can allocate new child commitments, steer existing work, trigger follow-up turns and interrupt active child turns across its current organization. - Why this is / is not agent-owned: graph/mailbox/session machinery enforces decisions, but the model chooses whether and how to allocate/steer/intervene from current whole-tree feedback. Removing the root model leaves control primitives without the discretionary S3 judgment. - Evidence: agentcontrol.rs; agentcontrolgateway.rs; wait.rs. - Basis: explicit + structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material first-party complementary-audit path is established at the assessed root-tree recursion. - Disturbance / variety regulated: not established as an independent discrepancy between ordinary current-control reporting and operational reality. - Decisive decision or feedback right: not established. - Decision owner: none established for S3. - Supporting / enforcement mechanisms: arbitrary child agents can inspect workspace state; UI metadata includes verifier/reviewer profiles; repository development/benchmark surfaces contain verification machinery. These do not by themselves establish S3. - Closure path: not applicable; no reviewed standard runtime path establishes complementary access → materially independent audit judgment → finding returned into root S3/control. - Claim being audited: no function-specific first-party audit claim is wired into standard root-tree operation. - Ordinary reporting path: child status, last task, mailbox results and canonical Thread/Turn/Item events flow through the ordinary AgentControl/runtime substrate. - Complementary access path: generic children can be asked to review and can inherit/fork context, but spawnagent exposes a generic task/message/model constructor rather than a function-specific independent audit path; generic prompt expressiveness does not meet Methodology C. - Independence boundary: no standard audit-specific actor, sensor boundary or independently owned verifier closure was established. - Who acts on findings: a root or user could act on an arbitrary review response, but that is a possible downstream composition rather than a first-party S3 closure. - Why this is / is not agent-owned: no S3 function is established before ownership classification. - Evidence: agentcontrol.rs; teamPresets.ts. - Basis: explicit + structural absence review -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material first-party external-and-prospective organizational adaptation loop is established at the assessed recursion. - Disturbance / variety regulated: not established as future/external change requiring adaptation of the root-agent organization&#39;s capability or structure. - Decisive decision or feedback right: not established. - Decision owner: none established for S4. - Supporting / enforcement mechanisms: web/MCP/tool research, provider/model selection, Skills discovery/install/configuration, reusable procedures and persistent task context can extend operation but do not by themselves establish S4. - Closure path: not applicable; no standard first-party path closes external/prospective sensing → generation of organizational adaptation options → S4 judgment → returned capability/current-control change. - Why this is / is not agent-owned: model research and Skill/tool use are available to S1 tasks; current task learning or user-driven capability configuration is not automatically organizational adaptation. - Evidence: README.md; lime-rs/crates/app-server/src/runtime/skills.rs. - Basis: explicit + structural absence review -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no material first-party identity/ultimate-policy decision loop is established at the assessed recursion. - Disturbance / variety regulated: not established as an identity/constitutional/ultimate-policy matter. - Decisive decision or feedback right: not established. - Decision owner: none established for S5. - Supporting / enforcement mechanisms: system prompts, model/provider configuration, permissions/approval gates, tool policies, Skills/profile metadata and user constraints govern operational behavior but do not establish ultimate-policy authority. - Closure path: not applicable; no reviewed path shows an identity/ultimate-policy issue reaching legitimate ultimate authority and returning as authoritative policy governing later root-tree operation. - Why this is / is not agent-owned: root and child models act within configured operational constraints; they are not shown owning the legitimacy/identity of those constraints. - Evidence: README.md; agentcontrol.rs. - Basis: explicit + structural absence review -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c27b3b98564bb101fde7bbe14fbc11d4a82d12b0/assessments/lime.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c27b3b98564bb101fde7bbe14fbc11d4a82d12b0\">c27b3b9 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-09-18T23:12:56+03:00\"><th scope=\"row\"><a href=\"https://github.com/RunMaestro/Maestro\" target=\"_blank\" rel=\"noopener\">Maestro</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-18\">2026-09-18</time></td><td class=\"review-ref\"><a href=\"https://github.com/RunMaestro/Maestro/tree/32ecbc14fe832138e9a7af4f263d1026a8aa8a5b\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 32ecbc14fe832138e9a7af4f263d1026a8aa8a5b\">32ecbc1 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously execute project/coding tasks inside individual provider-agent sessions controlled through Maestro. - Disturbance / variety regulated: open-ended codebase state, implementation uncertainty, tool output, tests and task-specific context. - Decisive decision or feedback right: choose substantive coding/research/tool actions needed to complete the assigned prompt/task. - Decision owner: the model-driven supported coding agent running as a Maestro session. - Supporting / enforcement mechanisms: session spawning/resume, project cwd, provider CLI integration, Auto Run task feeding, worktrees and message transport. - Closure path: Maestro sends a task/prompt to an agent session; the agent performs work and returns output/state; Maestro records and can feed the next task/turn. - Why this is / is not agent-owned: provider models own operational action choices; Maestro supplies the first-party harness that invokes and preserves their sessions. - Evidence: README, Group Chat docs and provider/session architecture. - Basis: explicit + structural -\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: - State: A - Function: coordinate multiple agent sessions so work is routed to suitable agents while avoiding concurrent edit interference and stale shared-project state. - Disturbance / variety regulated: two agent processes can edit the same files simultaneously, overwrite each other and continue from stale state; multi-agent questions can also require selective delegation/follow-up across project contexts. - Decisive decision or feedback right: choose which agents to involve and whether more rounds are needed; standard availability policy holds a request when the selected agent is already busy. - Decision owner: the model-driven Group Chat moderator owns agent/round selection; deterministic Maestro availability machinery enforces the selected coordination safely. - Supporting / enforcement mechanisms: “Only work with agents that are free” default, busy-state detection/holding, per-agent process/workdir, @mention routing, isolated worktrees and group message queue. - Closure path: moderator selects agents; Maestro delays any busy conflicting target until free while other agents proceed; returned responses go back to the moderator, which follows up or synthesizes before returning to the user. - Why this is / is not agent-owned: the runtime&#39;s busy check is enforcement, not the organizational owner; the autonomous moderator decides participant selection and continuation, with the safety relation altering when chosen S1 work actually runs. - Evidence: docs/group-chat.md, README and Group Chat source modules. - Basis: explicit + structural - Confidence: high - Caveats: worktrees/queues alone would not establish S2; the positive mapping relies on the documented same-file concurrency disturbance plus moderator/availability feedback loop. - Distinct S1 units: separate local or remote provider-agent processes, each in its own agent/project context. - Inter-S1 disturbance: concurrent processes editing the same files can overwrite one another and leave both conversations acting on stale state. - Attenuating coordination relation: the moderator routes work while the default availability policy holds requests to busy agents; separate worktrees can additionally isolate intentionally parallel writes. - Feedback into subsequent S1 behaviour: busy/free state delays or releases the requested invocation, and member responses return to the moderator for follow-up/delegation/synthesis. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the cited first-party behavior exists specifically to attenuate a concrete interaction hazard among distinct active agent processes, not merely to pass messages.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no distinct whole-system current-control function is established beyond task/session orchestration. - Disturbance / variety regulated: provider errors, cost/usage, session state and playbook progress are monitored, but no separate whole-fleet current-control owner with organizational discretion is established. - Decisive decision or feedback right: no material first-party owner was found that sees the whole system and reallocates current resources/commitments/priorities on behalf of the whole. - Decision owner: none established for qualifying S3. - Supporting / enforcement mechanisms: usage dashboard, Auto Run tracking, resilience/failover, queues, session discovery and remote control. - Closure path: no qualifying distinct S3 loop was found. - Why this is / is not agent-owned: moderator routing is counted as S2; dashboards, retries and failover are observation/runtime recovery rather than a demonstrated agent-owned S3 decision right. - Evidence: README, Group Chat docs and architecture. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no sufficiently independent complementary audit loop is established by the standard distribution. - Disturbance / variety regulated: code diffs, agent output filtering and moderator follow-up were inspected, but they do not constitute independent organizational audit. - Decisive decision or feedback right: no distinct reviewer/auditor right with complementary evidence access and corrective return was found. - Decision owner: none established for qualifying S3. - Supporting / enforcement mechanisms: diff viewer, logs/history, moderator synthesis/follow-up and provider-native tests/tools. - Closure path: no first-party independent audit finding → correction/reassignment loop is established. - Why this is / is not agent-owned: a moderator asking for more information or a human inspecting diffs is part of normal operation/review, not an evidenced independent S3 channel. - Evidence: README, Group Chat docs and architecture. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no separate external/prospective adaptation loop is established for the Maestro fleet. - Disturbance / variety regulated: changing provider availability and future project needs were inspected, but existing resilience is operational recovery. - Decisive decision or feedback right: no material first-party owner was found that senses external/future distinctions, develops adaptation options and returns a selected option into present capability/S3. - Decision owner: none established for qualifying S4. - Supporting / enforcement mechanisms: provider resilience/failover, documentation graph, usage analytics and user-authored playbooks. - Closure path: failover/retry restores current operation; it does not close an outside-and-then capability adaptation loop. - Why this is / is not agent-owned: recovery from overload/quota and analytics are S1/support mechanisms unless connected to prospective option generation and capability change. - Evidence: README features and architecture/docs. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no identity/ultimate-policy governance loop is established for the Maestro fleet. - Disturbance / variety regulated: user specifications, playbooks and app settings constrain tasks but do not establish organizational identity authority. - Decisive decision or feedback right: no material first-party ultimate-policy decision path with legitimate authority and return was found. - Decision owner: none established for qualifying S5. - Supporting / enforcement mechanisms: user prompts/specs, playbooks, moderator settings, agent/provider configuration and read-only mode. - Closure path: configuration and prompts affect tasks directly; no identity-level authority closure is established. - Why this is / is not agent-owned: a user being able to configure agents or choose a moderator is not sufficient for VSM S5. - Evidence: README, Group Chat management docs and application configuration surfaces. - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/9f83e41179680c24cbe23a5091abda11fcc221d0/assessments/maestro.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 9f83e41179680c24cbe23a5091abda11fcc221d0\">9f83e41 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-09-21T19:46:27+03:00\"><th scope=\"row\"><a href=\"https://github.com/cuga-project/cuga-agent\" target=\"_blank\" rel=\"noopener\">CUGA</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-21\">2026-09-21</time></td><td class=\"review-ref\"><a href=\"https://github.com/cuga-project/cuga-agent/tree/b3bdcaee74aaf7a53d3fb621b781d305fb714f5d\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision b3bdcaee74aaf7a53d3fb621b781d305fb714f5d\">b3bdcae &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: perform substantive enterprise/web/API/tool work through an iterative model-selected action and observation loop. - Disturbance / variety regulated: ambiguous user goals, changing browser/API/tool state, retrieved data, tool errors, generated-code outcomes, conversation context and intermediate task results. - Decisive decision or feedback right: choose the next substantive code/tool/action step from current task context and observations, and decide whether to continue acting or return a final answer. - Decision owner: the running CUGA model agent. - Supporting / enforcement mechanisms: CugaAgent, CugaLite/shared agent graph, code extraction, CodeExecutor, variables/state storage, tool registry/MCP adapters, budgets, policy gates, context management and checkpointer-backed thread state. - Closure path: user/host task → model call → model-selected executable action/tool use → first-party execution → returned output/variables → next model call → revised action or final answer. - Boundary reachability: CUGA ships the SDK/CLI/server runtime and the shared graph used by supported CugaAgent execution; buildagentgraph explicitly closes the callmodel &lt;-&gt; execute loop, so no downstream harness implementation is required to obtain the operational feedback path. - Why this is / is not agent-owned: deterministic runtime code parses, constrains and executes model output, but removing the model actor removes the discretionary choice of substantive next action from current observations. - Evidence: README.md, src/cuga/sdk.py, src/cuga/backend/cugagraph/nodes/cugaagentcore/graph/sharedgraph.py, src/cuga/backend/cugagraph/nodes/cugaagentcore/graph/sharednodes.py. - Basis: explicit + structural. - Confidence: high. - Caveats: model-provider inference is execution substrate and is not imported as a separate organizational owner.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party path establishes a specific inter-S1 interference/oscillation plus a distinct attenuation relation that changes later S1 behaviour. - Disturbance / variety regulated: no qualifying cross-S1 disturbance is established at the reviewed recursion. - Decisive decision or feedback right: not established for S2. - Decision owner: not established for S2. - Supporting / enforcement mechanisms: supervisor delegation tools, sequential delegation isolation, shared/supervisor variables, result transport, task todos, budgets and external-agent routing. - Closure path: not applicable. - Why this is / is not agent-owned: the supervisor model chooses and sequences subordinate work, but delegation, routing, shared variables and sequencing are not S2 without evidence that they attenuate a concrete disturbance among distinct operational S1 units. - Evidence: src/cuga/backend/cugagraph/nodes/cugasupervisor/prompts/supervisorliteprompt.jinja2, src/cuga/backend/cugagraph/nodes/cugasupervisor/delegation.py, src/cuga/backend/cugagraph/nodes/cugasupervisor/nodes/executeagenttool.py. - Basis: explicit absence after function-first review. - Confidence: high. - Caveats: a downstream deployment could add a real collision/resource-contention relation, but generic supervisor choreography does not establish that relation for the repository-level assessment.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: in supported CugaSupervisor mode, regulate the current whole-team portfolio by selecting subordinate agents and changing later commitments from accumulated current results and shared variables. - Disturbance / variety regulated: changing intermediate results, missing data, subordinate outputs that alter what work remains, and the need to choose which specialist should take the next current commitment. - Decisive decision or feedback right: choose which configured subordinate agent to invoke next, what task/context to give it and whether current evidence warrants another delegation or completion. - Decision owner: the model-driven CugaSupervisor actor. - Supporting / enforcement mechanisms: complete configured agent catalog, availableagents, selectedagents, agentresults, per-agent histories/variables, supervisor variables, generated delegation code, variable bridge, code executor, budgets and optional plan-approval gate. - Closure path: current task + whole configured team catalog + accumulated subordinate outcomes → supervisor model chooses next delegation/task → first-party delegated CugaAgent runs → result/variables are recorded in supervisor state → next supervisor model step revises the current team commitment or finishes. - Boundary reachability: CugaSupervisor is exported by the first-party SDK and the repository ships its graph, prompt, state and delegation machinery; internal subordinates are ordinary first-party CugaAgent instances, so the current-control path is available without a downstream scheduler or supervisor implementation. - Why this is / is not agent-owned: the runtime exposes the agent tools and deterministically executes generated delegation code, but the supervisor model owns the discretionary current-team choice of which specialist receives the next commitment and how returned team evidence changes subsequent work. - Evidence: src/cuga/sdk.py, src/cuga/backend/cugagraph/nodes/cugasupervisor/cugasupervisorgraph.py, src/cuga/backend/cugagraph/nodes/cugasupervisor/cugasupervisorstate.py, src/cuga/backend/cugagraph/nodes/cugasupervisor/nodes/prepareagentsandprompt.py, src/cuga/backend/cugagraph/nodes/cugasupervisor/nodes/executeagenttool.py. - Basis: explicit + structural. - Confidence: medium-high. - Caveats: the positive claim is not based on the word Supervisor. It rests on the shipped whole-team catalog plus accumulated subordinate outcomes feeding a model-owned decision over subsequent team commitments. Static budgets/approval are supporting constraints, not S3 ownership. - Whole-system current view: the supervisor receives the configured team catalog and persists the set of selected agents together with current per-agent results, histories and variables plus aggregated supervisor variables across the active task. - Current-control decision scope: assign the next current subtask to any configured subordinate, condition that assignment on prior team results/variables, retry or redirect work through another specialist, and terminate the team task when the current portfolio is sufficient.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material first-party path establishes sufficiently independent complementary access to operational reality beyond CUGA&#39;s ordinary production/reporting path. - Disturbance / variety regulated: not established as S3 at the reviewed boundary. - Decisive decision or feedback right: not established for a sufficiently independent audit function. - Decision owner: not established. - Supporting / enforcement mechanisms: pre-execute VERIFY, post-execution reflection, policy/tool guards, activity tracking, telemetry and run histories. - Closure path: VERIFY can return a revision instruction into the ordinary agent loop and reflection can append a summary of execution output, but those are routine production-checking closures rather than independent complementary audit. - Why this is / is not agent-owned: VERIFY/reflection can be model-driven, yet agent autonomy does not make a routine verifier S3. The inspected checks use the production task/history/variables/proposed code or just-produced execution output and run inside the same operational graph rather than obtaining materially different access to operational reality. - Evidence: src/cuga/backend/cugagraph/nodes/cugalite/reflection/preexecute.py, src/cuga/backend/cugagraph/nodes/cugalite/adapter/sandboxnode.py, src/cuga/backend/cugagraph/nodes/cugalite/reflection/reflection.py. - Basis: structural absence review. - Confidence: high. - Caveats: a deployment can attach an independent evaluator through external tooling; that adjacent evaluator is not imported into the standalone repository mapping.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material first-party path establishes an external-and-prospective adaptation loop whose adaptation judgment is owned inside the assessed CUGA boundary. - Disturbance / variety regulated: not established as repository-local S4. - Decisive decision or feedback right: not established inside CUGA for creating future-oriented adaptation options from environmental change. - Decision owner: not established inside the assessed boundary. - Supporting / enforcement mechanisms: optional Evolve client integration, durable/user memory, installed skills, standing event flows, knowledge/RAG, reflection and configuration/publish surfaces. - Closure path: the Evolve integration can send trajectories/facts to an external Evolve service and later inject returned guidelines/preferences into future prompts, but the adaptation judgment and guideline generation occur in that external service. Other inspected first-party mechanisms persist or trigger information without developing a repository-local prospective adaptation option. - Why this is / is not agent-owned: CUGA transports trajectories to Evolve and consumes Evolve output, but removing the external Evolve decision service removes the adaptation judgment while the first-party client machinery remains. Installed skills are read-only at runtime (loadskill), and standing flows execute future events rather than adapt CUGA capability in response to a modeled future. - Evidence: src/cuga/backend/evolve/integration.py, src/cuga/backend/evolve/memory.py, src/cuga/backend/skills/tools.py, src/cuga/backend/events/runtime.py. - Basis: explicit + structural absence review. - Confidence: medium-high. - Caveats: Evolve may itself implement a qualifying adaptation function at a wider assembled-system boundary; that would be a different system-in-focus and requires its own evidence rather than importing external behavior into CUGA.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no material first-party path establishes identity/ethos/ultimate-policy adjudication for the CUGA organization at the declared recursion. - Disturbance / variety regulated: no identity-level or S3-S4 policy tension is shown reaching a legitimate ultimate authority and returning as governing identity/policy. - Decisive decision or feedback right: not established for S5. - Decision owner: not established. - Supporting / enforcement mechanisms: administrator-authored policy objects, Intent Guards, Playbooks, Tool Guides/Tool Guards, Tool Approval/HITL, plan approval, prompts/instructions, permissions and configuration management. - Closure path: policy matching can block, guide, require approval or modify tool behavior for current work, but no identity/ultimate-policy issue → legitimate authority decision → returned governing-policy closure is established. - Why this is / is not agent-owned: models may apply or respond to configured policies and humans may approve ordinary delegations/actions, but those are operational constraints/approvals. The code explicitly describes policy code as administrator-authored; it does not supply an agent-owned or parent-governed identity adjudication process merely because policy is mutable. - Evidence: src/cuga/backend/cugagraph/policy/models.py, src/cuga/sdk.py, src/cuga/backend/cugagraph/nodes/cugasupervisor/nodes/executeagenttool.py. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: an organization deploying CUGA may supply its own legitimate governance authority and encode resulting policies through these surfaces; that parent organization is outside the standalone repository boundary.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/ccb2be0014ef50da558cc79fb5212eef3aa228d0/assessments/cuga.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit ccb2be0014ef50da558cc79fb5212eef3aa228d0\">ccb2be0 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"2\" data-assessment-at=\"2026-09-27T13:41:05+00:00\"><th scope=\"row\"><a href=\"https://github.com/github/gh-aw\" target=\"_blank\" rel=\"noopener\">GitHub Agentic Workflows</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>2</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-27\">2026-09-27</time></td><td class=\"review-ref\"><a href=\"https://github.com/github/gh-aw/tree/ff2eccd10a30d6a7bfaf0da449194e907a206555\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision ff2eccd10a30d6a7bfaf0da449194e907a206555\">ff2eccd &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: perform substantive repository work requiring model interpretation/reasoning, including tasks such as triage, review, failure investigation, documentation maintenance, dependency analysis and repository reporting. - Disturbance / variety regulated: ambiguous natural-language instructions; changing issue/PR/repository state; tool observations; model uncertainty; external data available through permitted tools; task-specific errors and incomplete evidence. - Decisive decision or feedback right: choose the next context-sensitive reasoning/tool action needed to satisfy the workflow instructions and revise later actions in response to returned observations. - Decision owner: the model-driven agent actor executed by the first-party generated agent job. - Supporting / enforcement mechanisms: compiler-generated job; selected built-in engine adapter; sandbox; network allowlist/firewall; GitHub/MCP tool allowlists; context assembly; read-only token posture; run/turn/resource bounds; structured safe-output interface. - Closure path: trigger + runtime-loaded workflow instructions -&gt; generated agent job invokes the selected model-driven actor -&gt; actor interprets current context and calls permitted tools -&gt; observations return to the agent execution -&gt; later actions/output change accordingly -&gt; a substantive task result or structured requested mutation is produced. - Boundary reachability: the README defines agentic workflows specifically as Markdown/frontmatter compiled into GitHub Actions that run AI agents, and the supported standard path wires built-in engines into the generated agent job; no adjacent dogfood agent is required for this operational loop. - Why this is / is not agent-owned: removing the model-driven actor while retaining the compiler, sandbox, permissions and safe-output machinery leaves enforcement and transport but not the contextual decision about what repository action/reasoning step to attempt next. - Evidence: README.md; docs/src/content/docs/reference/faq.md; docs/src/content/docs/guides/working-with-workflows.mdx. - Basis: explicit + structural. - Confidence: high. - Caveats: Copilot/Claude/Codex/Gemini/Pi provider internals remain external systems. A credits the agent actor in the first-party gh-aw execution path, not higher-order functions internal to any provider.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: attenuate concrete interference among concurrently active S1 workflow cells by serializing contexts that would collide while allowing independent work to proceed without sharing a cancellation/resource slot. - Disturbance / variety regulated: concurrent runs for the same issue/PR/ref displacing one another; multiple agent jobs exhausting one engine slot; safe-output jobs applying duplicate/conflicting mutations; conclusion jobs colliding; fan-out children cancelling one another because they inherit the same static job-level concurrency group. - Decisive decision or feedback right: determine whether a run/job must queue, may execute concurrently, should cancel an outdated peer, or requires a unique job discriminator to avoid unintended contention. - Decision owner: constructor-defined gh-aw concurrency policy generated from workflow/event identity and configured concurrency fields; no model actor owns the collision semantics. - Supporting / enforcement mechanisms: per-workflow concurrency groups; per-engine groups; queue: max; cancel-in-progress; safe-outputs.concurrency-group; conclusion-job group; concurrency.job-discriminator; GitHub Actions concurrency enforcement. - Closure path: concurrent S1/job intents reach generated concurrency grouping -&gt; gh-aw assigns the relevant common or disjoint group and queue/cancel policy -&gt; a conflicting run waits/cancels while independent/discriminated work proceeds -&gt; the admitted/queued outcome changes which S1 executes next and prevents the named collision from reaching operation. - Boundary reachability: concurrency groups and queue/discriminator behavior are compiler-generated first-party runtime configuration in the supported standard distribution; they do not require an adopter to invent a separate coordination protocol. - Why this is / is not agent-owned: the same queue/cancel/discriminator decision occurs if the worker model is removed and the compiler/runtime policy remains. The function-specific path therefore exists as C, not A. - Distinct S1 units: independently triggered model-driven workflow runs and fan-out worker workflow runs that own separate repository-work outcomes under the same gh-aw organization. - Inter-S1 disturbance: siblings can compete for the same issue/PR/ref execution slot, engine capacity, output-application lane or static fan-out slot, causing cancellation, duplicate mutation, resource exhaustion or conclusion collision. - Attenuating coordination relation: event-specific concurrency groups serialize genuinely shared contexts; per-engine groups cap shared model capacity; safe-output/conclusion groups serialize collision-prone post-processing; job-discriminator separates independent fan-out children that should not compete. - Feedback into subsequent S1 behaviour: queued runs execute only after the current holder completes, outdated PR runs can be cancelled, and discriminated fan-out children receive distinct slots so their operational jobs continue instead of being displaced. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the mapping is tied to explicit documented collision/resource-contention classes and generated attenuation rules that alter later S1 admission/execution; orchestrator fan-out or delegation alone is not used as the S2 witness. - Evidence: docs/src/content/docs/reference/concurrency.md; docs/src/content/docs/patterns/orchestrator-ops.md. - Basis: explicit + structural. - Confidence: high. - Caveats: dispatch/call-workflow topology is corroborating evidence for distinct operational cells, not S2 by itself. The positive S2 mapping rests on explicit interference and attenuation.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3 / regulation: - State: C - Function: regulate current workflow resource consumption and execution admission from aggregate/current run state using first-party budget and concurrency policy. - Disturbance / variety regulated: a single run consuming excessive AI credits; one workflow consuming excessive credits across a rolling 24-hour window; agent jobs over-consuming shared engine capacity; unbounded concurrent execution disrupting current service/resource availability. - Decisive decision or feedback right: determine whether a current run may start/continue under its per-run and rolling daily resource envelope and whether current jobs may enter a shared engine/concurrency slot. - Decision owner: constructor/workflow-configuration policy resolved and enforced by first-party gh-aw compiler/runtime paths. Workflow authors or organization variables can set thresholds, but no separately closed parent S3 mode with the required whole-system current view and discretionary returned decision is established at the reviewed boundary. - Supporting / enforcement mechanisms: max-ai-credits; max-daily-ai-credits; AWF firewall budget enforcement; rolling 24-hour usage accounting; generated environment/config resolution; per-engine concurrency; warning/failure reporting; disable/bypass rules for explicitly user-initiated invocations. - Closure path: current run/rolling usage and concurrent-slot state are evaluated -&gt; configured first-party budget/concurrency rule admits, queues, throttles or blocks execution -&gt; agent start/continuation changes accordingly -&gt; subsequent current operation remains inside the resolved resource envelope. - Boundary reachability: AI-credit guardrails and generated concurrency controls are normative shipped gh-aw runtime/compiler behavior and are active through ordinary compiled workflow execution. - Why this is / is not agent-owned: model actors do not decide whether the organization should exceed the configured budget/concurrency envelope. The decisive regulatory policy is constructor/configuration-owned; runtime enforcement executes it. - Whole-system current view: for the declared workflow organization, rolling 24-hour AI-credit accounting aggregates consumption across runs, while generated concurrency/resource state tracks admission to shared workflow/engine slots rather than only one model turn&#39;s local state. - Current-control decision scope: current resource/credit budget, current run admission/continuation and shared execution capacity. Tool choice, prompt interpretation and safe-output content remain operational or audit matters rather than S3 ownership. - Evidence: docs/src/content/docs/specs/ai-credits-specification.md; docs/src/content/docs/reference/concurrency.md; actions/setup/md/aicreditsratelimiterror.md; actions/setup/md/dailyworkflowaicexceeded.md. - Basis: explicit + structural. - Confidence: high. - Caveats: safe-outputs.steer, GitHub Environment review and organization-level variables provide useful human/operator controls, but they are not promoted to S3 parent mode here because the frozen standard path does not establish the complete parent whole-system-current-view -&gt; discretionary S3 decision -&gt; returned whole-system operation closure required for (P).\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: independently challenge the producing agent&#39;s proposed output/code changes for security-relevant failures before privileged mutation is applied. - Disturbance / variety regulated: prompt-injected behavior; leaked credentials/secrets; malicious or suspicious code patches; producing-agent claims that are unsafe when checked against the actual structured output, patch and workflow context. - Decisive decision or feedback right: judge whether the produced artifact contains one or more configured threat classes and return a structured approve/block finding with reasons before safe outputs are applied. - Decision owner: the separate threat-detection agent invocation that analyzes the producer&#39;s artifacts/context and emits the security judgment. Deterministic result parsing and safe-output gating enforce that judgment but do not own it. - Supporting / enforcement mechanisms: dedicated detection job; staged workflow prompt/context; agentoutput.json; aw.patch; configurable detection engine; structured JSON verdict; optional pre/post scanners; blocking/failure path into safeoutputs; scoped write separation. - Closure path: producing agent finishes -&gt; artifacts are staged into the separate threat-detection job -&gt; detection actor inspects workflow context/output/patch -&gt; verdict/reasons are emitted -&gt; a detected threat blocks or conditions the safe-output lane -&gt; privileged repository mutation therefore changes according to complementary findings. - Boundary reachability: threat detection is automatically enabled with safe outputs by default, runs as a distinct generated job before supported safe-output writes, and can use a separate built-in engine; no adjacent repository dogfood reviewer is required. - Why this is / is not agent-owned: removing the detection model actor while retaining the parser/gate leaves no equivalent semantic judgment over prompt injection, secret leakage or malicious patches. Conversely, removing the gate leaves a judgment but not enforcement. The audit judgment is therefore agent-owned while enforcement remains supporting machinery. - Claim being audited: that the producing agent&#39;s proposed structured output and code patch are safe enough to enter the privileged safe-output application path. - Ordinary reporting path: the main agent job produces normal task output / structured safe-output items and patch artifacts from its operational context. - Complementary access path: the separate detection job receives the raw structured output, patch, prompt/import context and workflow intent rather than relying only on the producing agent&#39;s self-report. - Independence boundary: detection executes after the main agent in a distinct job/context, can use a separately configured built-in engine and owns no production step; the producer cannot select the trusted detection-job identity from its own output. - Who acts on findings: generated safe-output/control logic blocks or withholds privileged writes when the audit finding is unsafe; tracking/reporting surfaces may additionally expose the finding to maintainers. - Evidence: docs/src/content/docs/reference/threat-detection.md; docs/src/content/docs/reference/safe-outputs.md; docs/src/content/docs/specs/safe-outputs-specification.md. - Basis: explicit + structural. - Confidence: high. - Caveats: using the same provider/model family for producer and detector does not make their contexts/roles identical, but it can correlate failure modes. The positive mapping relies on job/context separation and complementary raw-artifact access, not on a claim of statistical independence between model weights.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material first-party external-and-prospective adaptation loop is established in the supported gh-aw distribution at the pinned boundary. - Disturbance / variety regulated: not applicable for a positive S4 mapping. - Decisive decision or feedback right: not established. - Decision owner: none established at this boundary. - Supporting / enforcement mechanisms: experiment assignment/analysis, audit/forecast/reporting, dependency/model catalog updates, external tools/search and repository-maintenance workflows were inspected but do not by themselves close S4. - Closure path: no qualifying external-distinction -&gt; prospective adaptation option -&gt; adopted change to present organizational capability loop is established. - Why this is / is not agent-owned: the repository contains learning/analysis/experimentation machinery, but no standard autonomous actor is shown owning a future-capability adaptation decision that closes back into the assessed organization. - Evidence: docs/src/content/docs/experimental/experiments-specification.md; docs/src/content/docs/reference/audit.md; docs/src/content/docs/specs/forecast-specification.md. - Basis: explicit + structural negative review. - Confidence: high. - Caveats: repository-local dogfood agents may propose improvements to gh-aw itself, but contributor/R&amp;D loops are adjacent to the assessed product distribution and cannot be imported as runtime S4 ownership.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S5 / identity: - State: P - Function: preserve legitimate repository-owner authority over the workflow organization&#39;s load-bearing purpose/instructions across runs and return an authoritative policy/purpose amendment into later operation. - Disturbance / variety regulated: drift between the repository owner&#39;s intended workflow purpose and the instructions actually governing future agent runs; need to replace or refine top-level task/policy instructions without allowing an ordinary operational agent to silently become ultimate authority. - Decisive decision or feedback right: accept and commit an authoritative change to the Markdown workflow body that defines what the agent is to accomplish and the policy/instruction context governing later runs. - Decision owner: the legitimate repository owner/maintainer acting at the parent recursion through repository write/governance authority. No first-party autonomous gh-aw actor is established as ultimate authority over its own workflow identity. - Supporting / enforcement mechanisms: authoritative .md workflow source; repository write/merge controls; runtime body loading; compiler separation between runtime-loaded body and compiled frontmatter; GitHub revision history. - Closure path: identity/purpose/instruction issue is resolved by the legitimate repository parent -&gt; parent changes/accepts the authoritative Markdown workflow body -&gt; the body remains the source consumed at runtime -&gt; the next workflow run loads the amended instructions -&gt; subsequent S1 operation is governed by the returned parent decision. - Boundary reachability: runtime loading of the Markdown body is a documented standard gh-aw behavior: changes to instructions, output templates, context, conditions and examples take effect on the next run without recompilation. The return path is therefore part of ordinary supported execution rather than a project-specific dogfood loop. - Why this is / is not agent-owned: an operational agent may propose repository changes through safe outputs, but repository authority still determines whether the load-bearing workflow source changes. The agent does not acquire legitimate ultimate-policy authority merely by being able to draft a patch. - Identity / ultimate-policy issue: what durable purpose/instructions define this agentic workflow across executions, including a parent decision to replace or refine those load-bearing instructions. - Ultimate authority in each claimed mode: parent mode only — legitimate repository owner/maintainer authority over the authoritative workflow source. No supported autonomous S5 mode is established. - Return-to-operation path: committed Markdown-body amendment -&gt; runtime body load on the next trigger -&gt; model-driven S1 receives changed authoritative instructions -&gt; later work follows the amended purpose/policy. - Evidence: README.md; docs/src/content/docs/guides/working-with-workflows.mdx; docs/src/content/docs/reference/faq.md. - Basis: explicit + structural. - Confidence: high. - Caveats: a prompt or static config alone would not establish S5. The positive mapping rests on the parent-owned authoritative amendment plus the documented runtime reload that returns the changed purpose/policy into subsequent operation. Run-scoped steering and generic write approvals are current-control/authorization mechanisms and are not used as the S5 witness.\">P</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/ba863eaf455fd9a272f15cfff80e840aa8a6de07/assessments/gh-aw.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit ba863eaf455fd9a272f15cfff80e840aa8a6de07\">ba863ea &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-09-19T14:59:46+03:00\"><th scope=\"row\"><a href=\"https://github.com/langchain-ai/deepagentsjs\" target=\"_blank\" rel=\"noopener\">Deep Agents JS</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-19\">2026-09-19</time></td><td class=\"review-ref\"><a href=\"https://github.com/langchain-ai/deepagentsjs/tree/39b85021d5c64d14539999490610970f76da0b47\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 39b85021d5c64d14539999490610970f76da0b47\">39b8502 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously execute a bounded user/application task through model reasoning, tool/filesystem actions, optional delegation and returned observations. - Disturbance / variety regulated: task ambiguity, changing tool/filesystem results, model uncertainty, intermediate failures, context pressure and information returned by delegated workers. - Decisive decision or feedback right: choose the next substantive model/tool/delegation action, interpret returned observations and decide when to produce the final operational result. - Decision owner: the running model-driven root Deep Agent. - Supporting / enforcement mechanisms: LangGraph execution, filesystem backend, planning/todo support, summarization, checkpoint/store support, configured tools, subagent middleware, memory/skills and optional HITL. - Closure path: request enters createDeepAgent runtime → model selects response/tool/filesystem/delegation action → first-party runtime executes the selected callable path → result returns as agent state/messages → model chooses the next action or final response. - Boundary reachability: createDeepAgent is the documented first-party package entrypoint and immediately constructs a runnable model/tool agent with built-in filesystem, context and subagent support; no adopter-authored supervisory actor is required for this S1 loop. - Why this is / is not agent-owned: configuration bounds the action space, but the substantive sequence of tool/delegation/final-response choices is selected by the model agent at runtime rather than predetermined by a static workflow. - Evidence: libs/deepagents/README.md, libs/deepagents/src/agent.ts, libs/deepagents/src/middleware/subagents.ts. - Basis: explicit + structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party S2 interference-attenuation function is established among distinct operational subagents at the reviewed recursion. - Disturbance / variety regulated: multiple subagents can run independently or concurrently, but no shipped organizational relation is evidenced that senses a specific inter-S1 conflict/oscillation and mutually adjusts those S1 units to attenuate it. - Decisive decision or feedback right: none established for qualifying S2 coordination. - Decision owner: none established. - Supporting / enforcement mechanisms: root-controlled task delegation, isolated/fork context, parallel independent calls, filtered state transfer, per-agent call-count isolation, persisted async task state and root-owned async lifecycle controls. - Closure path: not applicable; worker results return hierarchically to the root and async lifecycle actions are S3 current-control interventions, not an S2 feedback relation among peers. - Why this is / is not agent-owned: the root can choose workers and manage their commitments, but selection/delegation/control from a parent does not establish S2 without a concrete cross-S1 disturbance and attenuation loop. - Evidence: libs/deepagents/src/middleware/subagents.ts, libs/deepagents/src/middleware/asyncsubagents.ts. - Basis: explicit + absence review -\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: regulate the root agent&#39;s current set of remote asynchronous subagent commitments using live status and model-selected interventions. - Disturbance / variety regulated: background work can become stale, fail, complete, require changed instructions, consume attention after it is no longer needed, or need to be replaced/augmented while other tasks continue. - Decisive decision or feedback right: choose which async commitment to start, inspect, redirect/interrupt, cancel or retain based on the current tracked task set and returned statuses/results. - Decision owner: the autonomous root Deep Agent invoking the model-facing async-task control tools. - Supporting / enforcement mechanisms: asyncTasks persisted reduced state, Agent Protocol/LangGraph SDK clients, remote thread/run identifiers, live-status fetches, multitaskStrategy: &quot;interrupt&quot;, run cancellation, task-list merging and optional completion callbacks. - Closure path: root agent starts one or more async subagents → first-party middleware records the full tracked set → listasynctasks/checkasynctask returns live current status/result into the root model&#39;s context → root agent selects update/interrupt, cancel, new work or no intervention → first-party tool executes the decision and writes the changed task state → subsequent model steps observe the changed current operation. - Boundary reachability: configuring AsyncSubAgent entries directly mounts the five first-party control tools into createDeepAgent; the root model itself can invoke them without an adopter supplying a separate manager/controller actor. - Why this is / is not agent-owned: SDK/runtime machinery enforces the selected lifecycle action, but the root model owns the discretionary decision of which current commitment to inspect, redirect, cancel or add. - Evidence: libs/deepagents/src/agent.ts, libs/deepagents/src/middleware/asyncsubagents.ts, libs/deepagents/src/middleware/completioncallback.ts. - Basis: explicit + structural - Confidence: high - Caveats: ordinary synchronous delegation alone is not this witness. S3 rests on the separately shipped async mode with persistent whole-set visibility and intervention rights. - Whole-system current view: the root holds a persisted asyncTasks map for all tracked background tasks and can use listasynctasks to fetch their live statuses in one current view or checkasynctask for detailed status/result. - Current-control decision scope: start new commitments; inspect active commitments; interrupt and replace a running task&#39;s instruction on the same thread; cancel work that is no longer needed; and condition subsequent action on completion/error/cancellation state.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material first-party operational complementary-audit/challenge function is established at the reviewed JS runtime boundary. - Disturbance / variety regulated: tests/evals can detect behavioural regressions and a parent may inspect worker results, but no shipped operating actor independently challenges an S1/S3 claim through complementary access and returns an audit judgment into corrective current control. - Decisive decision or feedback right: none established for a qualifying S3 function. - Decision owner: none established. - Supporting / enforcement mechanisms: behavioural eval suites, LangSmith experiment reporting, integration/unit tests, ordinary parent inspection of task results, HITL tool approval and callback notifications were inspected but not credited as audit ownership. - Closure path: not applicable; repository evals run as development/evaluation workspaces and record/assert trajectories, while normal worker-result checking remains in the producing/control path rather than an independent complementary audit channel. - Why this is / is not agent-owned: separate evaluation execution or a human permission prompt does not by itself establish organizational audit independence, complementary access and corrective feedback into live operation. - Evidence: evals/README.md, runtime middleware tree at the pinned revision, libs/deepagents/src/middleware/asyncsubagents.ts, libs/acp/src/server.ts. - Basis: explicit + absence review -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no distinct first-party prospective environment-facing intelligence/adaptation loop is established at the reviewed organizational boundary. - Disturbance / variety regulated: persistent memory and skills can preserve user feedback, preferences, project context and procedures across later calls, but persistence/retrieval alone does not establish S4 outside-and-then adaptation ownership. - Decisive decision or feedback right: none established for a qualifying S4 function. - Decision owner: none established. - Supporting / enforcement mechanisms: AGENTS.md memory loading/editing, model instructions to save useful feedback, skill sources, persistent filesystem state, summarization, checkpoints and repository eval results. - Closure path: not applicable for S4; memory/skill files can change later prompt context, but the pinned runtime does not separately sense future/external distinctions, develop adaptation alternatives, decide among them and return the chosen organizational adaptation into current capability/control. - Why this is / is not agent-owned: the model may write remembered facts/preferences or edit procedures, but those actions are context maintenance within the ordinary operational loop rather than an evidenced S4 environmental intelligence/adaptation organ. - Evidence: libs/deepagents/src/middleware/memory.ts, skills/filesystem support in libs/deepagents/src/agent.ts, evals/README.md. - Basis: explicit + absence review -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party identity/ultimate-policy authority loop is established at the reviewed Deep Agents JS organization boundary. - Disturbance / variety regulated: system prompts, filesystem permissions, harness profiles, ACP modes and tool approvals constrain operation, but they are configured/enforced operational rules rather than an evidenced S5 identity/ultimate-policy decision process. - Decisive decision or feedback right: none established for qualifying S5 identity/ultimate-policy closure. - Decision owner: none established. - Supporting / enforcement mechanisms: application-authored system prompts, harness profiles, tool exclusions, filesystem permissions, interruptOn, ACP allow/reject decisions, plan/agent/ask modes and custom middleware. - Closure path: not applicable; operator/developer configuration and per-tool permission responses alter allowed execution but no shipped path elevates an identity/ultimate-policy issue to a legitimate ultimate authority and returns that decision as organizational policy closure. - Why this is / is not agent-owned: the root agent operates within supplied identity/constraints; it does not own the ultimate authority that defines or revises the organization&#39;s identity/purpose, and generic human veto over a tool call is not S5 parent governance. - Evidence: libs/deepagents/src/agent.ts, libs/acp/README.md, libs/acp/src/server.ts, profile/permission support at the pinned revision. - Basis: explicit + absence review -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/cfa868d444561df00840fba12a7108868061303e/assessments/deepagentsjs.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit cfa868d444561df00840fba12a7108868061303e\">cfa868d &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"2\" data-assessment-at=\"2026-09-17T04:39:04+03:00\"><th scope=\"row\"><a href=\"https://github.com/NousResearch/hermes-agent\" target=\"_blank\" rel=\"noopener\">Hermes Agent</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>2</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-17\">2026-09-17</time></td><td class=\"review-ref\"><a href=\"https://github.com/NousResearch/hermes-agent/tree/16bddc88dd325c5eef27c2cc71bbb14c16b870aa\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 16bddc88dd325c5eef27c2cc71bbb14c16b870aa\">16bddc8 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: persistent Hermes profiles autonomously use tools, execute conversational/scheduled/board work and maintain operational state. Kanban workers are independent full processes with distinct profile identities and bounded task ownership.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: current first-party modes establish distinct S1 units, concrete disturbances and closed coordination responses. Bot Mode agents autonomously choose to pass or hand work to named peers while the room runtime bounds repeated turns. In Kanban, the default LLM decomposer chooses assignees and dependency edges that change which workers may run, while shared claims/dependencies/recovery suppress duplicate execution, invalid ordering and retry thrashing. The model/profile owns meaningful coordination discretion; deterministic room/dispatcher machinery transports and enforces those decisions.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3 / regulation: Hermes exposes a dedicated autonomous current-control construction path, but does not supply one universally active autonomous S3 owner. An explicitly configured orchestrator profile can receive board-wide discovery/routing primitives, create/link/unblock work and act separately from implementation workers; the decomposed root also returns to its orchestrator for completion judgment and further commitments. Developer/operator configuration still selects that profile and grants the broader kanban surface, so the autonomous path is Constructor-level rather than out-of-box A.\">C(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: Hermes supplies a first-party complementary-review construction path. kanbanrequestreview can transfer a completed implementation into a distinct review run, and a reviewer can requestchanges, closing the review and routing the task back to the original implementer. Kanban Swarm separately gates synthesis on a verifier that reads every worker handoff/blackboard update and may pass only when evidence is sufficient. However, reviewer/verifier identity and independence are selected by configuration/topology rather than guaranteed by a single standard autonomous auditor, so the correct state is Constructor.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: memory/skill background review, routines and self-improvement can alter later behavior, but they learn from current/internal experience or schedule work. No distinct externally and prospectively oriented intelligence function was established that develops future adaptation options in a two-way S3–S4 loop.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: profiles, prompts, permissions, tools and orchestration settings are user/developer authored. Human control over ordinary board commitments is S3-level parent regulation, not evidence of identity- or ultimate-policy-level closure.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/3c4e337ba7c21469cb290647676a4f3ce60d81ac/assessments/hermes-agent.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 3c4e337ba7c21469cb290647676a4f3ce60d81ac\">3c4e337 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-09-24T23:28:02+03:00\"><th scope=\"row\"><a href=\"https://github.com/sethkarten/continual-harness\" target=\"_blank\" rel=\"noopener\">Continual Harness</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-24\">2026-09-24</time></td><td class=\"review-ref\"><a href=\"https://github.com/sethkarten/continual-harness/tree/bbab97ad73e460b7cd7c08527d10ced30cc03fbe\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision bbab97ad73e460b7cd7c08527d10ced30cc03fbe\">bbab97a &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: pursue the environment objective through a continuing model-driven PokeAgent loop that observes current state, chooses first-party tools/actions, receives their results and continues until the episode/run terminates. - Disturbance / variety regulated: changing game state, screenshots/map/state observations, objective progress, tool/action outcomes, local failures, context pressure and open-ended next-action choice. - Decisive decision or feedback right: choose the next substantive environment/tool action from current operating context and returned observations. - Decision owner: the model-driven PokeAgent actor assembled and driven by the first-party runtime. - Supporting / enforcement mechanisms: server/MCP adapter, scaffold-specific tool registry, conversation/run state, trajectory logging, persistent stores, context handling and execution bounds. - Closure path: environment/context → PokeAgent model turn → model-selected action/tool → first-party execution/environment feedback → updated context → next model turn. - Boundary reachability: run.py directly launches the in-repository agent path; continualharness is a documented first-party scaffold. - Why this is / is not agent-owned: model-provider inference is environmental, but the first-party runtime defines the operating loop, context/tool surface and return path while the model-driven actor owns substantive next-action choice. - Evidence: README.md; agents/PokeAgent.py; run.py. - Basis: explicit + structural. - Confidence: high. - Caveats: external model-provider or alternate external-CLI organization is not imported into this S1 claim.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party disturbance-specific coordination loop among distinct viable S1 units is established at the declared boundary. - Disturbance / variety regulated: local/custom subagents, tool calls and harness components may interact during one operating task, but no sibling-unit oscillation, contention or incompatible-assumption disturbance is detected and attenuated by a distinct relation. - Decisive decision or feedback right: no S2-specific conflict/attenuation decision right is established. - Decision owner: not established for S2. - Supporting / enforcement mechanisms: subagent/tool registry, sequential operating loop, objective progression, custom subagent execution and persistence. - Closure path: operational delegation/tool use returns results to the orchestrator; no separate inter-S1 disturbance → attenuation → feedback closure is established. - Boundary reachability: subordinate subagent mechanisms are reachable, but plurality/topology is not treated as S2 by itself. - Why this is / is not agent-owned: delegation and component interaction do not prove a coordination function without the required disturbance-specific relation. - Evidence: agents/PokeAgent.py; agents/tools/registry.py. - Basis: structural negative search. - Confidence: high. - Caveats: a generated/custom subagent organization could create a downstream S2 relation, but it would require separate evidence. - Distinct S1 units checked: main PokeAgent and subordinate/custom subagent executions reachable in the standard scaffold. - Inter-S1 disturbance checked: task handoff/tool use and shared trajectory context do not establish mutual operational interference. - Why generic communication/routing/delegation is insufficient: the main operating actor initiates subordinate work and receives a result; no independent coordination loop resolves a disturbance between viable units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no distinct first-party current-management function with a whole-organization present view and intervention authority is established. - Disturbance / variety regulated: step scheduling, objective state, local replanning, context compaction and evolution timing constrain individual operation but do not constitute whole-system resource/commitment/current-priority management. - Decisive decision or feedback right: no actor is established that receives a present whole-organization view and reallocates resources, priorities, commitments or accountability among operating units. - Decision owner: not established for S3. - Supporting / enforcement mechanisms: deterministic run lifecycle, adaptive evolution schedule, objective state and local operating/tool limits. - Closure path: these mechanisms constrain or advance one current run; no distinct present-management judgment → cross-operation intervention → returned feedback loop closes. - Boundary reachability: mechanisms are first-party and reachable, but classified by function rather than by names such as planner/orchestrator. - Why this is / is not agent-owned: local operational planning and S4 adaptation do not automatically create S3 current control. - Evidence: agents/PokeAgent.py; agents/utils/harnessevolver.py. - Basis: structural negative search. - Confidence: high. - Caveats: richer alternate PokeAgent modes expose planning helpers, but the selected continualharness boundary excludes built-in subagents and still does not establish installation-level S3 ownership.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material independent complementary audit/challenge function with corrective closure is established in the reviewed continualharness mode. - Disturbance / variety regulated: trajectories, tool failures and current outcomes are inspected by the Refiner, but that evidence feeds S4 adaptation rather than a distinct current complementary-audit function. - Decisive decision or feedback right: no separate audit actor with independent discrepancy judgment and corrective return is reachable in the selected scaffold. - Decision owner: not established for S3. - Supporting / enforcement mechanisms: trajectory/run logs, evolution analysis and verifier/reflection subagents present in richer repository modes. - Closure path: Refiner observations return as persistent future-capability changes under S4. subagentverify is explicitly excluded from continualharness and cannot supply current audit closure here. - Boundary reachability: run.py sets EXCLUDEBUILTINSUBAGENTS=1 for continualharness; the registry omits built-in subagent tools including subagentverify under that setting. - Why this is / is not agent-owned: repository-wide existence of verifier code is insufficient when it is outside the selected standard path. - Evidence: run.py; agents/tools/registry.py; agents/PokeAgent.py. - Basis: explicit + structural negative search. - Confidence: high. - Caveats: a downstream or alternate scaffold that enables a materially independent verifier is a different operating boundary and would require its own evidence; no such verifier is credited to the frozen Continual Harness mode.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:4\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A - Function: use accumulated operating evidence to autonomously choose persistent changes to the installed agent harness so subsequent S1 operation has changed future capability. - Disturbance / variety regulated: recurring navigation/tool failures, stalled objectives, ineffective subagents/skills, prompt shortcomings, memory gaps/staleness and other patterns across recent trajectories. - Decisive decision or feedback right: decide which prompt, subagent, skill and memory mechanisms should be created, changed or retired in response to accumulated evidence. - Decision owner: the model-driven first-party HarnessEvolver/Refiner invoked automatically by the continuing runtime. - Supporting / enforcement mechanisms: adaptive evolution schedule; recent-trajectory extraction; separate prompt/subagent/skill/memory evolution passes; persistent first-party stores; evolution log; bootstrap/load surfaces. - Closure path: S1 trajectories/failures → scheduled HarnessEvolver → Refiner interpretation and chosen durable mutations → persistent prompt/subagent/skill/memory state → continuing PokeAgent consumes changed state on later steps without episode reset. - Boundary reachability: --scaffold continualharness --enable-prompt-optimization is documented and wired as the reference Continual Harness mode; PokeAgent constructs and invokes HarnessEvolver directly. - Why this is / is not agent-owned: deterministic scheduling decides when to inspect; the substantive adaptation choice is made by the model-driven Refiner and applied without requiring a human adaptation decision each cycle. - External distinction: S4 evidence is drawn from the operating environment and accumulated trajectory/tool-result failures produced by S1 interaction, not merely from static repository configuration or an internal search objective detached from ongoing operation. - Future / prospective distinction: the Refiner does not merely repair the just-completed action; it converts patterns across prior operation into durable changes intended to improve later steps of the same episode and, optionally, later bootstrapped runs. - Adaptation option generated: the Refiner autonomously proposes and implements concrete prompt rewrites plus create/update/retire operations over subagents, skills and memory based on the observed trajectory window. - Path back into current capability / S3: chosen mutations are written to first-party persistent harness stores and prompt state; the same continuing PokeAgent reloads/consumes those changed capability surfaces on subsequent S1 steps, while the evolution summary is returned into its continuing context. This is an S4→S1 capability return, not a claim of separate S3 ownership. - Evidence: README.md; agents/utils/harnessevolver.py; agents/PokeAgent.py; System-Design/architecture/harnessevolver.md. - Basis: explicit + structural. - Confidence: high. - Caveats: this S4 claim is specific to the concrete continuing organization. A separate meta-search system may have harness search/evolution as its S1 instead, as the Index records for Meta-Harness.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no material identity/ultimate-policy authority loop is established for the running Continual Harness organization. - Disturbance / variety regulated: scaffold selection, game/objective setup, model/backend choice, optimization enablement and fixed safety/tool constraints bound lower-level operation/adaptation. - Decisive decision or feedback right: no actor is shown adjudicating an identity/ultimate-policy issue and returning a newly decided policy that changes the legitimate organizational constitution. - Decision owner: not established for S5. - Supporting / enforcement mechanisms: CLI/configuration, scaffold/tool registry, fixed prompt constraints, operator-selected model/backend and optimization flags. - Closure path: operators/configuration establish lower-level constraints before or around operation; no runtime identity/policy issue → legitimate authority → returned constitutional policy closure is established. - Boundary reachability: configuration and policy-like constraints are first-party and reachable, but remain lower-level setup/enforcement surfaces. - Why this is / is not agent-owned: harness self-modification is bounded adaptation of operational capability, not evidence that the Refiner owns ultimate identity or policy defining what organization it may become. - Evidence: README.md; run.py; agents/tools/registry.py. - Basis: explicit + structural negative search. - Confidence: high. - Caveats: the Refiner can change prompts/skills/memory/subagents, but those delegated adaptation rights remain inside operator-selected scaffold/tool/safety boundaries and do not establish legitimate ultimate-policy authority.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/ab4029e53addc1436869f5443985215216045c3a/assessments/continual-harness.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit ab4029e53addc1436869f5443985215216045c3a\">ab4029e &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-09-19T14:46:24+03:00\"><th scope=\"row\"><a href=\"https://github.com/trpc-group/trpc-agent-go\" target=\"_blank\" rel=\"noopener\">tRPC-Agent-Go</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-19\">2026-09-19</time></td><td class=\"review-ref\"><a href=\"https://github.com/trpc-group/trpc-agent-go/tree/28cb50c1d927a586521de028aed95bde2a018144\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 28cb50c1d927a586521de028aed95bde2a018144\">28cb50c &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: execute bounded agent tasks through model-driven reasoning, tool/sub-agent selection, observation of returned results and final response generation. - Disturbance / variety regulated: request ambiguity, model uncertainty, tool/environment results, tool failures, session state and new information returned during execution. - Decisive decision or feedback right: choose model-generated next actions and tool calls, decide whether to delegate to an exposed specialist, use returned observations in later turns and terminate with a final answer. - Decision owner: the configured model-driven LLMAgent. - Supporting / enforcement mechanisms: Runner, tool execution, session/memory/state services, skill repository, callbacks/plugins, model generation bounds and cancellation/retry plumbing. - Closure path: user/application input enters Runner → LLMAgent evaluates context and emits response/tool/delegation choices → first-party runtime executes the selected callable path → results return into model context → LLMAgent continues or emits the final result. - Boundary reachability: LLMAgent and Runner are the documented primary execution path and require no adopter-authored control actor beyond selecting/configuring a model, tools and task instruction. - Why this is / is not agent-owned: Runner constrains execution and transports state, but substantive tool/delegation/final-response choices are produced by the model agent rather than a fixed workflow alone. - Evidence: docs/mkdocs/en/agent.md, agent/llmagent/llmagent.go, runner/runner.go. - Basis: explicit + structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: provide a first-party coordinator-Team construction path that can regulate interaction among multiple specialized member Agents by selecting member work, receiving their outputs and feeding those outputs into subsequent coordinator/member behavior. - Disturbance / variety regulated: independently produced specialist analyses can require combination, review, revision, shared context or ordering before one coherent answer can be produced. - Decisive decision or feedback right: within a configured coordinator Team, the coordinator model chooses which member(s) to call and how to synthesize/use returned results; the adopter still defines the specialists, role boundaries and concrete coordination objective. - Decision owner: model-driven coordinator Agent for runtime member selection/synthesis; application author for the organizational construction and disturbance-specific coordination contract. - Supporting / enforcement mechanisms: team.New, AgentTool wrappers, member result aggregation, configurable shared parent history, parallel member calls, WithSubAgents, transfer and agent interfaces. - Closure path: application supplies coordinator plus distinct members → coordinator selects members → members execute separate S1 work → results return as tool responses/shared history → coordinator can use the changed context for later member calls or final synthesis. - Boundary reachability: all runtime machinery for coordinator/member feedback is first-party and directly composable, but a qualifying S2 organization requires the adopter to supply distinct S1 roles and an actual interference/coordination contract. - Why this is / is not agent-owned: the framework owns the feedback mechanism and coordinator runtime, but not the organizational distinction that makes member interference material; therefore the path is constructor-owned rather than an autonomous packaged S2 organization. - Evidence: docs/mkdocs/en/team.md, docs/mkdocs/en/multiagent.md. - Basis: explicit + structural - Confidence: high - Caveats: ChainAgent, ParallelAgent, CycleAgent, Swarm handoff and generic delegation are not credited as S2 on their own. - Distinct S1 units: two or more configured member Agents, each capable of its own model/tool execution for a role-specific assignment. - Inter-S1 disturbance: specialist outputs may be incomplete, inconsistent or require review/revision/integration, but the concrete disturbance must be defined by the application&#39;s roles and coordinator instruction. - Attenuating coordination relation: the coordinator receives member outputs as tool results in shared context and can select additional member calls or synthesize/revise the combined answer. - Feedback into subsequent S1 behaviour: a member&#39;s returned result becomes coordinator context and can influence subsequent model choices, including another member invocation with updated context where the application has configured that relation. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the first-party Team supplies a coordinator-mediated closed feedback surface suitable for multi-member review/integration, but the framework intentionally leaves the concrete interference policy to the adopter; hence C instead of treating bare routing as S2 or claiming A.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no material first-party whole-system current-control function was established for the deployed agent organization. - Disturbance / variety regulated: Runner handles active invocation lifecycle, cancellation, retries and session state, but the reviewed first-party paths do not maintain an organizationally meaningful whole-system view of current commitments/resources and then choose interventions over them. - Decisive decision or feedback right: none established for qualifying S3 current-control decisions. - Decision owner: none established. - Supporting / enforcement mechanisms: Runner lifecycle, context cancellation, retry controls, CycleAgent termination, graph checkpoints/HITL and session state were inspected as mechanisms rather than S3 ownership. - Closure path: not applicable; these mechanisms execute or stop configured work but do not form a whole-system current-state → prioritization/resource/intervention → changed operations loop. - Why this is / is not agent-owned: coordinator Agents can choose specialist calls inside a task, but that is task-level orchestration/coordination rather than authority over the organization&#39;s current portfolio of commitments and resources. - Evidence: docs/mkdocs/en/agent.md, docs/mkdocs/en/multiagent.md, Runner/graph documentation inspected at the pinned revision. - Basis: explicit + absence review -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material first-party operational complementary-audit loop was established at the reviewed boundary. - Disturbance / variety regulated: tRPC-Agent-Go can evaluate outputs/traces and review completed sessions, but the reviewed built-in paths do not independently challenge an operational unit&#39;s current claims and return findings into corrective current control. - Decisive decision or feedback right: none established for a qualifying S3 audit function. - Decision owner: none established. - Supporting / enforcement mechanisms: Evaluation metrics, LLM Judge/static evaluators, Evolution Reviewer, effectiveness/safety/spec gates, revision audit logs and PromptIter validation are retained as evaluation/adaptation mechanisms. - Closure path: not applicable for S3; Evaluation produces persisted regression results, while Evolution/PromptIter use review signals for prospective skill/prompt change rather than a complementary current-control correction loop. - Why this is / is not agent-owned: some evaluators can use separate judge models, but independence of a scorer is insufficient when its organizational function is offline evaluation/adaptation and no first-party path returns audit findings into current operational correction. - Evidence: docs/mkdocs/en/evaluation/index.md, docs/mkdocs/en/evolution.md, docs/mkdocs/en/promptiter.md. - Basis: explicit + absence review -\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:4\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A(P) - Function: learn reusable future-facing operating procedures from completed interactions and make accepted adaptations available to subsequent agent tasks, with both autonomous promotion and an optional first-party parent-governed promotion mode. - Disturbance / variety regulated: repeated exploration cost, user corrections, recovered errors, recurring tool workflows, operational pitfalls and changes revealed by completed-task experience. - Decisive decision or feedback right: decide whether a completed-session delta merits review, form a reusable skill adaptation, and determine whether the resulting revision becomes active capability for later runs. In the base mode the reviewer-driven Evolution loop closes this without human approval; in the parent mode a human reviewer owns the final approve/reject judgment over a held revision. - Decision owner: base mode — the LLM Reviewer owns semantic adaptation generation while fixed first-party gates qualify/enforce publication; parent mode — the human reviewer reached through built-in HumanGate/ApprovalService owns the decisive promotion/rejection judgment. - Supporting / enforcement mechanisms: DefaultReviewPolicy, LLM Reviewer, Reconciler, SpecGate, SafetyGate, EffectivenessGate, HumanGate, ApprovalService, immutable revision store/active pointer, Publisher, shared skill repository, skillload, rollback and OpenClaw Evolution wiring. - Closure path: completed task/session and correction/recovery/tool-use distinctions → review policy → LLM Reviewer extracts reusable workflow → reconcile/gates qualify revision → autonomous mode publishes directly, or HumanGate holds it for parent approve/reject → approved revision is activated/published and repository refresh exposes it → a later similar task loads the skill and changes operational behavior. - Boundary reachability: Runner directly accepts WithEvolutionService; the standard distribution includes the no-human-gate autonomous path plus WithHumanGate, built-in hold gates and ApprovalService for the parent mode. The documented first-party Publisher/revision machinery returns either mode&#39;s accepted decision into the managed skill repository; no custom approval protocol is required. - Why this is / is not agent-owned: in the base mode the semantic adaptation candidate is generated by a dedicated reviewer model and fixed gates only constrain/enforce that agentic adaptation before it is returned to future capability. Enabling HumanGate deliberately transfers the decisive promotion judgment for held revisions to a parent human without removing the separately supported autonomous mode. - Evidence: docs/mkdocs/en/evolution.md, runner/runner.go, openclaw/app/evolutionruntime.go, evolution/revision.go, docs/mkdocs/en/promptiter.md. - Basis: explicit + structural - Confidence: high - Caveats: ordinary memory/history is not the positive witness. Offline optimizer and PromptIter are corroborating adaptation paths; the online Evolution loop independently establishes the base A. The parent mode is specific to Evolution revision promotion, not a generic S5 or organization-wide human approval claim. - External distinction: completed-session transcript evidence including multi-step tool use, explicit user correction and recovered errors; optional outcomes/evaluation evidence can further qualify candidate revisions. - Future / prospective distinction: the Reviewer abstracts reusable workflows/pitfalls from past executions specifically so later similar tasks avoid repeated exploration and failure. - Adaptation option generated: a structured managed SKILL.md revision (or, in separate first-party optimization modes, an improved skill/prompt candidate) with qualification state and revision history. - Path back into current capability / S3: after publish and repository refresh, the same repository used by LLMAgent exposes the managed skill to future runs through skill overview/skillload, directly changing the operational context and available proven procedure.\">A(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no material first-party runtime identity or ultimate-policy decision loop was established at the reviewed system boundary. - Disturbance / variety regulated: instructions, tool/sub-agent authorization, graph policy, Evolution gates and optional human approval can constrain behavior, but they do not constitute a first-party legitimate ultimate-authority process for deciding system identity/policy conflicts. - Decisive decision or feedback right: none established for qualifying S5 identity/ultimate-policy closure. - Decision owner: none established. - Supporting / enforcement mechanisms: LLMAgent instruction/system prompt, application-owned agent/sub-agent construction, tool authorization, configuration, Evolution HumanGate and graph HITL were inspected as policy inputs/enforcement or parent hooks. - Closure path: not applicable; the first-party framework consumes configured policy/approval decisions but does not itself establish an identity issue → ultimate authority → authoritative policy decision → returned operation loop. - Why this is / is not agent-owned: prompts and approval callbacks may encode or solicit policy, but the framework explicitly leaves application configuration/authorization to the adopter and does not infer ultimate authority from a human gate. - Evidence: docs/mkdocs/en/agent.md, docs/mkdocs/en/multiagent.md, docs/mkdocs/en/evolution.md. - Basis: explicit + absence review -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/7430d59595f20f0c2e5129e3877301d09e75e40c/assessments/trpc-agent-go.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 7430d59595f20f0c2e5129e3877301d09e75e40c\">7430d59 &#8599;</a></td></tr>"];
